if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface TranscriptResult {
  originalLanguage: string;
  originalTranscript: string;
  translatedLanguage: string;
  translatedTranscript: string;
}

export enum ProcessingStatus {
  IDLE = 'IDLE',
  UPLOADING = 'UPLOADING',
  ANALYZING = 'ANALYZING',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR'
}

export interface LanguageOption {
  code: string;
  name: string;
  flag: string;
}

export const SUPPORTED_LANGUAGES: LanguageOption[] = [
  { code: 'my', name: 'Burmese', flag: '🇲🇲' },
  { code: 'en', name: 'English', flag: '🇺🇸' },
  { code: 'th', name: 'Thai', flag: '🇹🇭' },
  { code: 'zh', name: 'Chinese (Simplified)', flag: '🇨🇳' },
  { code: 'ja', name: 'Japanese', flag: '🇯🇵' },
  { code: 'ko', name: 'Korean', flag: '🇰🇷' },
  { code: 'es', name: 'Spanish', flag: '🇪🇸' },
  { code: 'fr', name: 'French', flag: '🇫🇷' },
  { code: 'de', name: 'German', flag: '🇩🇪' },
  { code: 'vi', name: 'Vietnamese', flag: '🇻🇳' },
];

export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      // Remove the data URL prefix (e.g., "data:video/mp4;base64,")
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = (error) => reject(error);
  });
};

export const formatFileSize = (bytes: number): string => {
  if (bytes === 0) return '0 Bytes';
  const k = 1024;
  const sizes = ['Bytes', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
};

import { GoogleGenAI, Type } from "@google/genai";
import { TranscriptResult } from "../types";

export const generateTranscript = async (
  fileBase64: string,
  mimeType: string,
  targetLanguage: string
): Promise<TranscriptResult> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key is missing. Please check your environment configuration.");
  }

  const ai = new GoogleGenAI({ apiKey });

  const prompt = `
    Analyze the audio in this video file.
    1. Transcribe the spoken content verbatim in its original language.
    2. Translate the transcript into ${targetLanguage}.

    If there is no speech, indicate that in the transcript fields.
    Format the output as a clean JSON object.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: fileBase64,
            },
          },
          {
            text: prompt,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            originalLanguage: {
              type: Type.STRING,
              description: "The detected original language of the video (e.g., English, Japanese).",
            },
            originalTranscript: {
              type: Type.STRING,
              description: "The full verbatim transcript in the original language.",
            },
            translatedLanguage: {
              type: Type.STRING,
              description: `The target language name (should be ${targetLanguage}).`,
            },
            translatedTranscript: {
              type: Type.STRING,
              description: `The full translation of the transcript in ${targetLanguage}.`,
            },
          },
          required: ["originalLanguage", "originalTranscript", "translatedLanguage", "translatedTranscript"],
        },
      },
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response generated from the model.");
    }

    const result = JSON.parse(text) as TranscriptResult;
    return result;

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useCallback, useState } from 'react';
import { Upload, FileVideo, Youtube, AlertCircle } from 'lucide-react';

interface FileUploadProps {
  onFileSelect: (file: File) => void;
}

const FileUpload: React.FC<FileUploadProps> = ({ onFileSelect }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [showYoutubeAlert, setShowYoutubeAlert] = useState(false);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const files = e.dataTransfer.files;
    if (files && files.length > 0) {
      validateAndSelect(files[0]);
    }
  }, []);

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      validateAndSelect(e.target.files[0]);
    }
  };

  const validateAndSelect = (file: File) => {
    if (file.type.startsWith('video/') || file.type.startsWith('audio/')) {
       // Check for reasonable size limit for browser-based base64 (e.g., 100MB warning)
       if (file.size > 200 * 1024 * 1024) {
         alert("File is too large (>200MB). Please try a shorter clip or compress the video for this browser-based demo.");
         return;
       }
       onFileSelect(file);
    } else {
      alert("Please upload a valid video or audio file.");
    }
  };

  return (
    <div className="w-full max-w-2xl mx-auto space-y-6">
      <div 
        className={`relative border-2 border-dashed rounded-2xl p-10 transition-all duration-300 text-center cursor-pointer group
          ${isDragging 
            ? 'border-red-500 bg-red-500/10' 
            : 'border-zinc-700 hover:border-red-500/50 hover:bg-zinc-800/50'
          }`}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        onClick={() => document.getElementById('fileInput')?.click()}
      >
        <input 
          type="file" 
          id="fileInput" 
          className="hidden" 
          accept="video/*,audio/*"
          onChange={handleFileInput}
        />

        <div className="flex flex-col items-center justify-center space-y-4">
          <div className="p-4 rounded-full bg-zinc-800 group-hover:bg-zinc-700 transition-colors">
            <Upload className="w-8 h-8 text-zinc-400 group-hover:text-red-500" />
          </div>
          <div>
            <h3 className="text-xl font-semibold text-white mb-2">Upload Video File</h3>
            <p className="text-zinc-400 text-sm">Drag & drop or click to browse</p>
            <p className="text-zinc-500 text-xs mt-2">MP4, MOV, WebM, MP3 (Max 200MB)</p>
          </div>
        </div>
      </div>

      {/* YouTube URL Mock Input */}
      <div className="flex items-center space-x-2 bg-zinc-900 border border-zinc-800 rounded-xl p-2 pl-4">
         <Youtube className="w-5 h-5 text-red-500 flex-shrink-0" />
         <input 
           type="text" 
           placeholder="Paste YouTube URL..." 
           className="bg-transparent border-none outline-none text-sm w-full text-zinc-300 placeholder-zinc-600"
           onFocus={() => setShowYoutubeAlert(true)}
         />
         <button className="px-4 py-2 bg-zinc-800 text-zinc-400 text-xs rounded-lg hover:bg-zinc-700 font-medium transition-colors">
           Fetch
         </button>
      </div>

      {showYoutubeAlert && (
        <div className="bg-blue-500/10 border border-blue-500/20 p-4 rounded-xl flex items-start space-x-3 animate-in fade-in slide-in-from-top-2">
          <AlertCircle className="w-5 h-5 text-blue-400 flex-shrink-0 mt-0.5" />
          <div className="text-sm text-blue-200">
            <p className="font-medium mb-1">YouTube Direct Link Unavailable</p>
            <p className="text-blue-200/70">
              Due to browser security restrictions (CORS), web apps cannot directly download YouTube videos. 
              Please download the video using a tool like 4K Video Downloader or yt-dlp, then upload the file above.
            </p>
            <button 
              onClick={(e) => { e.stopPropagation(); setShowYoutubeAlert(false); }}
              className="mt-2 text-xs text-blue-400 hover:text-white underline"
            >
              Dismiss
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default FileUpload;

