import React, { useState } from 'react';
import { TranscriptResult } from '../types';
import { Copy, Check, Download } from 'lucide-react';

interface TranscriptDisplayProps {
  data: TranscriptResult;
}

const TranscriptDisplay: React.FC<TranscriptDisplayProps> = ({ data }) => {
  const [copiedOriginal, setCopiedOriginal] = useState(false);
  const [copiedTranslated, setCopiedTranslated] = useState(false);

  const copyToClipboard = async (text: string, isOriginal: boolean) => {
    try {
      await navigator.clipboard.writeText(text);
      if (isOriginal) {
        setCopiedOriginal(true);
        setTimeout(() => setCopiedOriginal(false), 2000);
      } else {
        setCopiedTranslated(true);
        setTimeout(() => setCopiedTranslated(false), 2000);
      }
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  const downloadText = () => {
    const content = `Original (${data.originalLanguage}):\n\n${data.originalTranscript}\n\n====================\n\nTranslated (${data.translatedLanguage}):\n\n${data.translatedTranscript}`;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `transcript_${data.originalLanguage}_to_${data.translatedLanguage}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="w-full space-y-6 animate-in fade-in slide-in-from-bottom-8 duration-500">
      <div className="flex justify-between items-center">
        <h2 className="text-xl font-bold text-white">Transcript & Translation</h2>
        <button 
          onClick={downloadText}
          className="flex items-center space-x-2 text-sm text-zinc-400 hover:text-white transition-colors"
        >
          <Download className="w-4 h-4" />
          <span>Download .txt</span>
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Original Transcript */}
        <div className="bg-zinc-900 border border-zinc-800 rounded-2xl overflow-hidden flex flex-col h-[500px]">
          <div className="p-4 border-b border-zinc-800 bg-zinc-900/50 flex justify-between items-center">
            <span className="text-sm font-semibold text-zinc-300 uppercase tracking-wider">
              {data.originalLanguage || 'Original'}
            </span>
            <button
              onClick={() => copyToClipboard(data.originalTranscript, true)}
              className="p-1.5 rounded-lg hover:bg-zinc-800 text-zinc-500 hover:text-zinc-300 transition-colors"
              title="Copy"
            >
              {copiedOriginal ? <Check className="w-4 h-4 text-green-500" /> : <Copy className="w-4 h-4" />}
            </button>
          </div>
          <div className="flex-1 p-6 overflow-y-auto font-serif text-lg leading-relaxed text-zinc-300 whitespace-pre-wrap">
            {data.originalTranscript}
          </div>
        </div>

        {/* Translated Transcript */}
        <div className="bg-zinc-900 border border-zinc-800 rounded-2xl overflow-hidden flex flex-col h-[500px] relative">
           <div className="absolute inset-0 bg-red-500/5 pointer-events-none" />
          <div className="p-4 border-b border-zinc-800 bg-zinc-900/50 flex justify-between items-center relative z-10">
            <div className="flex items-center space-x-2">
              <span className="text-sm font-semibold text-red-400 uppercase tracking-wider">
                {data.translatedLanguage}
              </span>
              <span className="px-1.5 py-0.5 rounded text-[10px] font-bold bg-red-500/20 text-red-400 border border-red-500/20">
                AI TRANSLATED
              </span>
            </div>
            <button
              onClick={() => copyToClipboard(data.translatedTranscript, false)}
              className="p-1.5 rounded-lg hover:bg-zinc-800 text-zinc-500 hover:text-zinc-300 transition-colors"
              title="Copy"
            >
              {copiedTranslated ? <Check className="w-4 h-4 text-green-500" /> : <Copy className="w-4 h-4" />}
            </button>
          </div>
          <div className="flex-1 p-6 overflow-y-auto font-serif text-lg leading-relaxed text-zinc-100 whitespace-pre-wrap relative z-10">
            {data.translatedTranscript}
          </div>
        </div>
      </div>
    </div>
  );
};

export default TranscriptDisplay;

import React, { useState, useRef } from 'react';
import { 
  ProcessingStatus, 
  TranscriptResult, 
  SUPPORTED_LANGUAGES 
} from './types';
import FileUpload from './components/FileUpload';
import LanguageSelector from './components/LanguageSelector';
import TranscriptDisplay from './components/TranscriptDisplay';
import { fileToBase64, formatFileSize } from './utils/fileUtils';
import { generateTranscript } from './services/geminiService';
import { Bot, Loader2, PlayCircle, RefreshCw, AlertTriangle, Sparkles } from 'lucide-react';

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);
  const [status, setStatus] = useState<ProcessingStatus>(ProcessingStatus.IDLE);
  const [targetLang, setTargetLang] = useState<string>('my'); // Default to Burmese (my)
  const [result, setResult] = useState<TranscriptResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);

  const handleFileSelect = (selectedFile: File) => {
    setFile(selectedFile);
    setFilePreview(URL.createObjectURL(selectedFile));
    setStatus(ProcessingStatus.IDLE);
    setResult(null);
    setError(null);
  };

  const handleReset = () => {
    setFile(null);
    setFilePreview(null);
    setStatus(ProcessingStatus.IDLE);
    setResult(null);
    setError(null);
    if (filePreview) URL.revokeObjectURL(filePreview);
  };

  const processVideo = async () => {
    if (!file) return;

    setStatus(ProcessingStatus.UPLOADING);
    setError(null);

    try {
      // Step 1: Convert to Base64
      setStatus(ProcessingStatus.ANALYZING);
      const base64Data = await fileToBase64(file);

      const targetLangName = SUPPORTED_LANGUAGES.find(l => l.code === targetLang)?.name || 'Burmese';

      // Step 2: Send to Gemini
      const data = await generateTranscript(base64Data, file.type, targetLangName);

      setResult(data);
      setStatus(ProcessingStatus.COMPLETED);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An error occurred while processing the video.");
      setStatus(ProcessingStatus.ERROR);
    }
  };

  return (
    <div className="min-h-screen bg-[#0f0f0f] text-white selection:bg-red-500/30">
      {/* Navbar */}
      <nav className="border-b border-zinc-800 bg-[#0f0f0f]/80 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-red-600 to-red-500 flex items-center justify-center">
              <Bot className="w-5 h-5 text-white" />
            </div>
            <span className="font-bold text-xl tracking-tight">TubeScribe</span>
          </div>
          <div className="flex items-center space-x-4">
             <a href="https://ai.google.dev" target="_blank" rel="noreferrer" className="text-xs font-medium text-zinc-500 hover:text-zinc-300 transition-colors">
               Powered by Gemini 2.0
             </a>
          </div>
        </div>
      </nav>

      <main className="max-w-7xl mx-auto px-4 py-12">
        <div className="flex flex-col items-center justify-center space-y-8 mb-12">
           <div className="text-center space-y-4 max-w-2xl">
             <h1 className="text-4xl md:text-5xl font-bold bg-clip-text text-transparent bg-gradient-to-b from-white to-zinc-400">
               Video to Burmese Transcript
             </h1>
             <p className="text-zinc-400 text-lg">
               Upload any video, and our AI will transcribe the audio and translate it into Burmese (or your language of choice) instantly.
             </p>
           </div>
        </div>

        {/* Content Area */}
        <div className="max-w-5xl mx-auto">
          {!file ? (
            <FileUpload onFileSelect={handleFileSelect} />
          ) : (
            <div className="space-y-8 animate-in fade-in zoom-in-95 duration-300">

              {/* Toolbar */}
              <div className="flex flex-col md:flex-row items-center justify-between bg-zinc-900/50 p-4 rounded-2xl border border-zinc-800 gap-4">
                 <div className="flex items-center space-x-4 w-full md:w-auto">
                    <div className="relative w-16 h-16 bg-black rounded-lg overflow-hidden flex-shrink-0 border border-zinc-800 group">
                      <video src={filePreview || ""} className="w-full h-full object-cover opacity-60" />
                      <PlayCircle className="absolute inset-0 m-auto w-6 h-6 text-white/80" />
                    </div>
                    <div className="min-w-0">
                      <h3 className="font-medium text-white truncate max-w-[200px]">{file.name}</h3>
                      <p className="text-xs text-zinc-500">{formatFileSize(file.size)} • {file.type.split('/')[1].toUpperCase()}</p>
                    </div>
                 </div>

                 <div className="flex items-center space-x-4 w-full md:w-auto">
                    <div className="flex-1 md:w-64">
                       <LanguageSelector 
                         selectedCode={targetLang} 
                         onSelect={setTargetLang} 
                         disabled={status === ProcessingStatus.ANALYZING || status === ProcessingStatus.UPLOADING}
                       />
                    </div>

                    {status === ProcessingStatus.IDLE || status === ProcessingStatus.ERROR || status === ProcessingStatus.COMPLETED ? (
                      <div className="flex space-x-2 pt-6">
                        <button 
                          onClick={handleReset}
                          className="p-3 rounded-xl bg-zinc-800 hover:bg-zinc-700 text-zinc-300 transition-colors"
                          title="Upload new file"
                        >
                          <RefreshCw className="w-5 h-5" />
                        </button>
                        <button 
                          onClick={processVideo}
                          disabled={status === ProcessingStatus.ANALYZING}
                          className="flex-1 px-6 py-3 bg-red-600 hover:bg-red-500 text-white font-medium rounded-xl transition-all shadow-lg shadow-red-900/20 flex items-center justify-center space-x-2"
                        >
                          <Sparkles className="w-5 h-5" />
                          <span>Generate Transcript</span>
                        </button>
                      </div>
                    ) : null}
                 </div>
              </div>

              {/* Status Display */}
              {(status === ProcessingStatus.ANALYZING || status === ProcessingStatus.UPLOADING) && (
                <div className="py-20 flex flex-col items-center justify-center space-y-6 text-center">
                  <div className="relative">
                    <div className="absolute inset-0 bg-red-500/20 blur-xl rounded-full animate-pulse"></div>
                    <Loader2 className="w-16 h-16 text-red-500 animate-spin relative z-10" />
                  </div>
                  <div className="space-y-2">
                     <h3 className="text-2xl font-semibold text-white">
                        {status === ProcessingStatus.UPLOADING ? "Preparing Video..." : "AI Analyzing Audio..."}
                     </h3>
                     <p className="text-zinc-400 max-w-md mx-auto">
                       Gemini is listening to the audio, transcribing speech, and translating it to {SUPPORTED_LANGUAGES.find(l => l.code === targetLang)?.name}. This may take a moment depending on the video length.
                     </p>
                  </div>
                </div>
              )}

              {/* Error Display */}
              {status === ProcessingStatus.ERROR && (
                <div className="bg-red-500/10 border border-red-500/20 rounded-2xl p-6 flex items-start space-x-4">
                   <AlertTriangle className="w-6 h-6 text-red-500 flex-shrink-0" />
                   <div>
                     <h3 className="text-red-200 font-medium">Processing Error</h3>
                     <p className="text-red-200/60 text-sm mt-1">{error}</p>
                     <p className="text-red-200/40 text-xs mt-2">Try a shorter video or check your API key quota.</p>
                   </div>
                </div>
              )}

              {/* Results */}
              {status === ProcessingStatus.COMPLETED && result && (
                <TranscriptDisplay data={result} />
              )}

            </div>
          )}
        </div>
      </main>

      <footer className="border-t border-zinc-900 mt-20 py-8 text-center text-zinc-600 text-sm">
        <p>&copy; {new Date().getFullYear()} TubeScribe. Built with React & Gemini 2.0 Flash.</p>
      </footer>
    </div>
  );
};

export default App;

export interface TranscriptSegment {
  startTime: string;
  endTime: string;
  originalText: string;
  translatedText: string;
}

