  IDLE = 'IDLE',
  UPLOADING = 'UPLOADING',
  ANALYZING = 'ANALYZING',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR'
}

export interface LanguageOption {
  code: string;
  name: string;
  flag: string;
}

export const SUPPORTED_LANGUAGES: LanguageOption[] = [
  { code: 'my', name: 'Burmese', flag: '🇲🇲' },
  { code: 'en', name: 'English', flag: '🇺🇸' },
  { code: 'th', name: 'Thai', flag: '🇹🇭' },
  { code: 'zh', name: 'Chinese (Simplified)', flag: '🇨🇳' },
  { code: 'ja', name: 'Japanese', flag: '🇯🇵' },
  { code: 'ko', name: 'Korean', flag: '🇰🇷' },
  { code: 'es', name: 'Spanish', flag: '🇪🇸' },
  { code: 'fr', name: 'French', flag: '🇫🇷' },
  { code: 'de', name: 'German', flag: '🇩🇪' },
  { code: 'vi', name: 'Vietnamese', flag: '🇻🇳' },
];

import { GoogleGenAI, Type } from "@google/genai";
import { TranscriptResult } from "../types";

export const generateTranscript = async (
  fileBase64: string,
  mimeType: string,
  targetLanguage: string
): Promise<TranscriptResult> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key is missing. Please check your environment configuration.");
  }

  const ai = new GoogleGenAI({ apiKey });

  const prompt = `
    Analyze the audio in this video file.
    1. Transcribe the spoken content verbatim in its original language, broken down into logical time segments (e.g., sentences or natural pauses).
    2. For each segment, provide the start and end timestamps in "MM:SS" format.
    3. Translate the text of each segment into ${targetLanguage}.

    If there is no speech, return an empty segments array.
    Format the output as a clean JSON object.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: fileBase64,
            },
          },
          {
            text: prompt,
          },
        ],
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            originalLanguage: {
              type: Type.STRING,
              description: "The detected original language of the video (e.g., English, Japanese).",
            },
            translatedLanguage: {
              type: Type.STRING,
              description: `The target language name (should be ${targetLanguage}).`,
            },
            segments: {
              type: Type.ARRAY,
              description: "List of transcript segments with timestamps.",
              items: {
                type: Type.OBJECT,
                properties: {
                  startTime: { type: Type.STRING, description: "Start time in MM:SS format" },
                  endTime: { type: Type.STRING, description: "End time in MM:SS format" },
                  originalText: { type: Type.STRING, description: "The original transcript text for this segment" },
                  translatedText: { type: Type.STRING, description: `The translation of this segment in ${targetLanguage}` }
                },
                required: ["startTime", "endTime", "originalText", "translatedText"]
              }
            }
          },
          required: ["originalLanguage", "translatedLanguage", "segments"],
        },
      },
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response generated from the model.");
    }

    const result = JSON.parse(text) as TranscriptResult;
    return result;

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { TranscriptResult } from '../types';
import { Copy, Check, Download, Clock } from 'lucide-react';

interface TranscriptDisplayProps {
  data: TranscriptResult;
}

const TranscriptDisplay: React.FC<TranscriptDisplayProps> = ({ data }) => {
  const [copiedOriginal, setCopiedOriginal] = useState(false);
  const [copiedTranslated, setCopiedTranslated] = useState(false);

  const getFullText = (isOriginal: boolean) => {
    return data.segments
      .map(s => isOriginal ? s.originalText : s.translatedText)
      .join('\n');
  };

  const copyToClipboard = async (isOriginal: boolean) => {
    try {
      const text = getFullText(isOriginal);
      await navigator.clipboard.writeText(text);
      if (isOriginal) {
        setCopiedOriginal(true);
        setTimeout(() => setCopiedOriginal(false), 2000);
      } else {
        setCopiedTranslated(true);
        setTimeout(() => setCopiedTranslated(false), 2000);
      }
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  const downloadSRT = () => {
    let srtContent = '';
    data.segments.forEach((segment, index) => {
      // Simple conversion of MM:SS to HH:MM:SS,ms format for SRT
      // Assuming inputs are MM:SS, adding 00: prefix and ,000 suffix
      const formatTime = (time: string) => {
        const parts = time.split(':');
        if (parts.length === 2) return `00:${time},000`;
        return `${time},000`;
      };

      srtContent += `${index + 1}\n`;
      srtContent += `${formatTime(segment.startTime)} --> ${formatTime(segment.endTime)}\n`;
      srtContent += `${segment.originalText}\n`;
      srtContent += `${segment.translatedText}\n\n`;
    });

    const blob = new Blob([srtContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `transcript_${data.originalLanguage}_to_${data.translatedLanguage}.srt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="w-full space-y-6 animate-in fade-in slide-in-from-bottom-8 duration-500">
      <div className="flex flex-wrap justify-between items-center gap-4">
        <h2 className="text-xl font-bold text-white">Transcript & Translation</h2>
        <div className="flex space-x-2">
           <button 
            onClick={() => copyToClipboard(true)}
            className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-zinc-800 hover:bg-zinc-700 text-xs font-medium text-zinc-300 transition-colors"
          >
            {copiedOriginal ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3" />}
            <span>Copy Original</span>
          </button>
           <button 
            onClick={() => copyToClipboard(false)}
            className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-zinc-800 hover:bg-zinc-700 text-xs font-medium text-zinc-300 transition-colors"
          >
            {copiedTranslated ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3" />}
            <span>Copy Translation</span>
          </button>
          <button 
            onClick={downloadSRT}
            className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-red-600 hover:bg-red-500 text-xs font-medium text-white transition-colors shadow-lg shadow-red-900/20"
          >
            <Download className="w-3 h-3" />
            <span>Download SRT</span>
          </button>
        </div>
      </div>

      <div className="bg-zinc-900 border border-zinc-800 rounded-2xl overflow-hidden flex flex-col max-h-[600px]">
        {/* Header */}
        <div className="grid grid-cols-12 gap-4 p-4 border-b border-zinc-800 bg-black/20 text-xs font-semibold text-zinc-500 uppercase tracking-wider sticky top-0 z-20 backdrop-blur-sm">
          <div className="col-span-2 md:col-span-1 text-center">Time</div>
          <div className="col-span-5 md:col-span-5 md:pl-4">{data.originalLanguage || 'Original'}</div>
          <div className="col-span-5 md:col-span-6 md:pl-4 text-red-400">{data.translatedLanguage}</div>
        </div>

        {/* Scrollable Content */}
        <div className="overflow-y-auto custom-scrollbar">
          {data.segments.length === 0 ? (
            <div className="p-8 text-center text-zinc-500">No speech detected.</div>
          ) : (
            data.segments.map((segment, index) => (
              <div 
                key={index} 
                className={`grid grid-cols-12 gap-4 p-4 border-b border-zinc-800/50 hover:bg-zinc-800/30 transition-colors group
                  ${index % 2 === 0 ? 'bg-zinc-900/30' : 'bg-transparent'}`}
              >
                {/* Timestamp */}
                <div className="col-span-2 md:col-span-1 flex items-start justify-center pt-1">
                  <div className="flex items-center space-x-1 text-xs font-mono text-zinc-500 bg-zinc-800/50 px-2 py-1 rounded">
                     <span>{segment.startTime}</span>
                  </div>
                </div>

                {/* Original Text */}
                <div className="col-span-5 md:col-span-5 md:pl-4 text-zinc-300 leading-relaxed text-sm md:text-base">
                  {segment.originalText}
                </div>

                {/* Translated Text */}
                <div className="col-span-5 md:col-span-6 md:pl-4 text-zinc-100 leading-relaxed text-sm md:text-base font-medium">
                  {segment.translatedText}
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

