import React, { useState, useEffect, useRef } from 'react';
import { TranscriptResult } from '../types';
import { Copy, Check, Download, Clock, Play } from 'lucide-react';

interface TranscriptDisplayProps {
  data: TranscriptResult;
  currentTime?: number;
  onSeek?: (time: number) => void;
}

const parseTimestamp = (timeStr: string): number => {
  if (!timeStr) return 0;
  const parts = timeStr.split(':').map(Number);
  if (parts.length === 2) return parts[0] * 60 + parts[1];
  if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
  return 0;
};

const TranscriptDisplay: React.FC<TranscriptDisplayProps> = ({ 
  data, 
  currentTime = 0, 
  onSeek 
}) => {
  const [copiedOriginal, setCopiedOriginal] = useState(false);
  const [copiedTranslated, setCopiedTranslated] = useState(false);
  const [autoScroll, setAutoScroll] = useState(true);
  const activeSegmentRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Find active segment
  const activeIndex = data.segments.findIndex((seg, index) => {
    const start = parseTimestamp(seg.startTime);
    const nextSeg = data.segments[index + 1];
    const end = nextSeg ? parseTimestamp(nextSeg.startTime) : parseTimestamp(seg.endTime);
    // Use the next segment's start time as the strict end for the current segment to avoid gaps
    return currentTime >= start && currentTime < end;
  });

  // Auto-scroll effect
  useEffect(() => {
    if (autoScroll && activeIndex !== -1 && activeSegmentRef.current) {
      activeSegmentRef.current.scrollIntoView({ 
        behavior: 'smooth', 
        block: 'center' 
      });
    }
  }, [activeIndex, autoScroll]);

  const getFullText = (isOriginal: boolean) => {
    return data.segments
      .map(s => isOriginal ? s.originalText : s.translatedText)
      .join('\n');
  };

  const copyToClipboard = async (isOriginal: boolean) => {
    try {
      const text = getFullText(isOriginal);
      await navigator.clipboard.writeText(text);
      if (isOriginal) {
        setCopiedOriginal(true);
        setTimeout(() => setCopiedOriginal(false), 2000);
      } else {
        setCopiedTranslated(true);
        setTimeout(() => setCopiedTranslated(false), 2000);
      }
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  const downloadSRT = () => {
    let srtContent = '';
    data.segments.forEach((segment, index) => {
      const formatTime = (time: string) => {
        const parts = time.split(':');
        if (parts.length === 2) return `00:${time},000`;
        return `${time},000`;
      };
      srtContent += `${index + 1}\n`;
      srtContent += `${formatTime(segment.startTime)} --> ${formatTime(segment.endTime)}\n`;
      srtContent += `${segment.originalText}\n`;
      srtContent += `${segment.translatedText}\n\n`;
    });

    const blob = new Blob([srtContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `transcript_${data.originalLanguage}_to_${data.translatedLanguage}.srt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="w-full space-y-6 animate-in fade-in slide-in-from-bottom-8 duration-500 h-full flex flex-col">
      <div className="flex flex-wrap justify-between items-center gap-4 flex-shrink-0">
        <h2 className="text-xl font-bold text-white">Transcript</h2>
        <div className="flex flex-wrap gap-2">
          <button
            onClick={() => setAutoScroll(!autoScroll)}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors border ${
              autoScroll 
                ? 'bg-blue-600/20 border-blue-500/50 text-blue-400 hover:bg-blue-600/30' 
                : 'bg-zinc-800 border-zinc-700 text-zinc-400 hover:bg-zinc-700'
            }`}
          >
            {autoScroll ? 'Auto-Scroll On' : 'Auto-Scroll Off'}
          </button>
           <button 
            onClick={() => copyToClipboard(true)}
            className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-zinc-800 hover:bg-zinc-700 text-xs font-medium text-zinc-300 transition-colors"
          >
            {copiedOriginal ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3" />}
            <span className="hidden sm:inline">Original</span>
          </button>
           <button 
            onClick={() => copyToClipboard(false)}
            className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-zinc-800 hover:bg-zinc-700 text-xs font-medium text-zinc-300 transition-colors"
          >
            {copiedTranslated ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3" />}
            <span className="hidden sm:inline">Translated</span>
          </button>
          <button 
            onClick={downloadSRT}
            className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-red-600 hover:bg-red-500 text-xs font-medium text-white transition-colors shadow-lg shadow-red-900/20"
          >
            <Download className="w-3 h-3" />
            <span className="hidden sm:inline">SRT</span>
          </button>
        </div>
      </div>

      <div className="bg-zinc-900 border border-zinc-800 rounded-2xl overflow-hidden flex flex-col flex-1 min-h-[500px] shadow-xl">
        {/* Header */}
        <div className="grid grid-cols-12 gap-4 p-4 border-b border-zinc-800 bg-black/40 text-xs font-semibold text-zinc-500 uppercase tracking-wider sticky top-0 z-20 backdrop-blur-md">
          <div className="col-span-2 md:col-span-2 lg:col-span-2 text-center">Time</div>
          <div className="col-span-5 md:col-span-5 lg:col-span-5 pl-2">{data.originalLanguage || 'Original'}</div>
          <div className="col-span-5 md:col-span-5 lg:col-span-5 pl-2 text-red-400">{data.translatedLanguage}</div>
        </div>

        {/* Scrollable Content */}
        <div ref={containerRef} className="overflow-y-auto custom-scrollbar flex-1 relative">
          {data.segments.length === 0 ? (
            <div className="p-12 text-center text-zinc-500 flex flex-col items-center">
              <Clock className="w-8 h-8 mb-3 opacity-50" />
              <p>No speech detected in this video.</p>
            </div>
          ) : (
            data.segments.map((segment, index) => {
              const isActive = index === activeIndex;
              return (
                <div 
                  key={index}
                  id={`segment-${index}`}
                  ref={isActive ? activeSegmentRef : null}
                  onClick={() => onSeek && onSeek(parseTimestamp(segment.startTime))}
                  className={`grid grid-cols-12 gap-4 p-4 border-b border-zinc-800/50 cursor-pointer transition-all duration-300 group
                    ${isActive 
                      ? 'bg-red-500/10 border-l-4 border-l-red-500' 
                      : 'hover:bg-zinc-800/40 border-l-4 border-l-transparent'
                    }`}
                >
                  {/* Timestamp */}
                  <div className="col-span-2 md:col-span-2 lg:col-span-2 flex items-start justify-center pt-1">
                    <div className={`flex items-center space-x-1 text-xs font-mono px-2 py-1 rounded transition-colors
                      ${isActive ? 'bg-red-500/20 text-red-300' : 'bg-zinc-800/50 text-zinc-500 group-hover:bg-zinc-700'}`}>
                       <Play className={`w-2 h-2 ${isActive ? 'fill-current' : 'hidden group-hover:block'}`} />
                       <span>{segment.startTime}</span>
                    </div>
                  </div>

                  {/* Original Text */}
                  <div className={`col-span-5 md:col-span-5 lg:col-span-5 pl-2 leading-relaxed text-sm md:text-base transition-colors
                    ${isActive ? 'text-white' : 'text-zinc-400 group-hover:text-zinc-300'}`}>
                    {segment.originalText}
                  </div>

                  {/* Translated Text */}
                  <div className={`col-span-5 md:col-span-5 lg:col-span-5 pl-2 leading-relaxed text-sm md:text-base font-medium transition-colors
                    ${isActive ? 'text-red-100' : 'text-zinc-200 group-hover:text-white'}`}>
                    {segment.translatedText}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>
  );
};

