import React, { useState, useRef } from 'react';
import { 
  ProcessingStatus, 
  TranscriptResult, 
  SUPPORTED_LANGUAGES 
} from './types';
import FileUpload from './components/FileUpload';
import LanguageSelector from './components/LanguageSelector';
import TranscriptDisplay from './components/TranscriptDisplay';
import { fileToBase64, formatFileSize } from './utils/fileUtils';
import { generateTranscript } from './services/geminiService';
import { Bot, Loader2, PlayCircle, RefreshCw, AlertTriangle, Sparkles, ChevronLeft } from 'lucide-react';

const App: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [filePreview, setFilePreview] = useState<string | null>(null);
  const [status, setStatus] = useState<ProcessingStatus>(ProcessingStatus.IDLE);
  const [targetLang, setTargetLang] = useState<string>('my'); // Default to Burmese (my)
  const [result, setResult] = useState<TranscriptResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [currentTime, setCurrentTime] = useState(0);

  const videoRef = useRef<HTMLVideoElement>(null);

  const handleFileSelect = (selectedFile: File) => {
    setFile(selectedFile);
    setFilePreview(URL.createObjectURL(selectedFile));
    setStatus(ProcessingStatus.IDLE);
    setResult(null);
    setError(null);
    setCurrentTime(0);
  };

  const handleReset = () => {
    setFile(null);
    setFilePreview(null);
    setStatus(ProcessingStatus.IDLE);
    setResult(null);
    setError(null);
    setCurrentTime(0);
    if (filePreview) URL.revokeObjectURL(filePreview);
  };

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      setCurrentTime(videoRef.current.currentTime);
    }
  };

  const handleSeek = (time: number) => {
    if (videoRef.current) {
      videoRef.current.currentTime = time;
      videoRef.current.play();
    }
  };

  const processVideo = async () => {
    if (!file) return;

    setStatus(ProcessingStatus.UPLOADING);
    setError(null);

    try {
      // Step 1: Convert to Base64
      setStatus(ProcessingStatus.ANALYZING);
      const base64Data = await fileToBase64(file);

      const targetLangName = SUPPORTED_LANGUAGES.find(l => l.code === targetLang)?.name || 'Burmese';

      // Step 2: Send to Gemini
      const data = await generateTranscript(base64Data, file.type, targetLangName);

      setResult(data);
      setStatus(ProcessingStatus.COMPLETED);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An error occurred while processing the video.");
      setStatus(ProcessingStatus.ERROR);
    }
  };

  return (
    <div className="min-h-screen bg-[#0f0f0f] text-white selection:bg-red-500/30">
      {/* Navbar */}
      <nav className="border-b border-zinc-800 bg-[#0f0f0f]/80 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3 cursor-pointer" onClick={handleReset}>
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-red-600 to-red-500 flex items-center justify-center">
              <Bot className="w-5 h-5 text-white" />
            </div>
            <span className="font-bold text-xl tracking-tight">TubeScribe</span>
          </div>
          <div className="flex items-center space-x-4">
             <a href="https://ai.google.dev" target="_blank" rel="noreferrer" className="text-xs font-medium text-zinc-500 hover:text-zinc-300 transition-colors">
               Powered by Gemini 2.0
             </a>
          </div>
        </div>
      </nav>

      <main className="max-w-[1600px] mx-auto px-4 py-8">

        {/* Header / Intro - Hide when Completed to save space */}
        {status !== ProcessingStatus.COMPLETED && (
          <div className="flex flex-col items-center justify-center space-y-8 mb-12 py-10">
             <div className="text-center space-y-4 max-w-2xl">
               <h1 className="text-4xl md:text-5xl font-bold bg-clip-text text-transparent bg-gradient-to-b from-white to-zinc-400">
                 Video to Burmese Transcript
               </h1>
               <p className="text-zinc-400 text-lg">
                 Upload any video, and our AI will transcribe the audio and translate it into Burmese (or your language of choice) instantly.
               </p>
             </div>
          </div>
        )}

        {/* Main Content */}
        {!file ? (
          <div className="max-w-5xl mx-auto">
            <FileUpload onFileSelect={handleFileSelect} />
          </div>
        ) : (
          <div className="animate-in fade-in zoom-in-95 duration-300">

            {/* COMPLETED VIEW - Split Screen */}
            {status === ProcessingStatus.COMPLETED && result ? (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Left Column: Video Player */}
                <div className="lg:col-span-1 space-y-4">
                   <div className="lg:sticky lg:top-24 space-y-4">
                      <div className="rounded-2xl overflow-hidden border border-zinc-800 bg-black shadow-2xl relative group">
                        <video
                          ref={videoRef}
                          src={filePreview || ""}
                          controls
                          className="w-full aspect-video object-contain"
                          onTimeUpdate={handleTimeUpdate}
                        />
                      </div>

                      <div className="bg-zinc-900/50 p-5 rounded-2xl border border-zinc-800 backdrop-blur-sm">
                        <h3 className="font-medium text-white truncate text-lg">{file.name}</h3>
                        <div className="flex items-center justify-between mt-2 text-sm text-zinc-400">
                          <span>{formatFileSize(file.size)}</span>
                          <span className="px-2 py-0.5 rounded bg-zinc-800 text-zinc-300 text-xs border border-zinc-700">
                             {file.type.split('/')[1].toUpperCase()}
                          </span>
                        </div>
                      </div>

                      <button 
                        onClick={handleReset}
                        className="w-full p-3 rounded-xl bg-zinc-800 hover:bg-zinc-700 text-zinc-300 hover:text-white transition-all flex items-center justify-center space-x-2 text-sm font-medium border border-zinc-700/50 hover:border-zinc-600"
                      >
                        <ChevronLeft className="w-4 h-4" />
                        <span>Process Another Video</span>
                      </button>
                   </div>
                </div>

                {/* Right Column: Transcript */}
                <div className="lg:col-span-2 min-h-[600px]">
                   <TranscriptDisplay 
                      data={result} 
                      currentTime={currentTime}
                      onSeek={handleSeek}
                   />
                </div>
              </div>
            ) : (
              // ANALYZING / SETUP VIEW
              <div className="max-w-5xl mx-auto space-y-8">
                {/* Toolbar */}
                <div className="flex flex-col md:flex-row items-center justify-between bg-zinc-900/50 p-4 rounded-2xl border border-zinc-800 gap-4">
                   <div className="flex items-center space-x-4 w-full md:w-auto">
                      <div className="relative w-16 h-16 bg-black rounded-lg overflow-hidden flex-shrink-0 border border-zinc-800 group">
                        <video src={filePreview || ""} className="w-full h-full object-cover opacity-60" />
                        <PlayCircle className="absolute inset-0 m-auto w-6 h-6 text-white/80" />
                      </div>
                      <div className="min-w-0">
                        <h3 className="font-medium text-white truncate max-w-[200px]">{file.name}</h3>
                        <p className="text-xs text-zinc-500">{formatFileSize(file.size)}</p>
                      </div>
                   </div>

                   <div className="flex items-center space-x-4 w-full md:w-auto">
                      <div className="flex-1 md:w-64">
                         <LanguageSelector 
                           selectedCode={targetLang} 
                           onSelect={setTargetLang} 
                           disabled={status === ProcessingStatus.ANALYZING || status === ProcessingStatus.UPLOADING}
                         />
                      </div>

                      {status === ProcessingStatus.IDLE || status === ProcessingStatus.ERROR ? (
                        <div className="flex space-x-2 pt-6">
                          <button 
                            onClick={handleReset}
                            className="p-3 rounded-xl bg-zinc-800 hover:bg-zinc-700 text-zinc-300 transition-colors"
                            title="Upload new file"
                          >
                            <RefreshCw className="w-5 h-5" />
                          </button>
                          <button 
                            onClick={processVideo}
                            className="flex-1 px-6 py-3 bg-red-600 hover:bg-red-500 text-white font-medium rounded-xl transition-all shadow-lg shadow-red-900/20 flex items-center justify-center space-x-2"
                          >
