                       <p className="text-zinc-400 max-w-md mx-auto">
                         Gemini is listening to the audio, transcribing speech, and translating it to {SUPPORTED_LANGUAGES.find(l => l.code === targetLang)?.name}. This may take a moment depending on the video length.
                       </p>
                    </div>
