  const videoRef = useRef<HTMLVideoElement>(null);
  const playerContainerRef = useRef<HTMLDivElement>(null);

  // Fullscreen event listeners
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };

    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => {
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
    };
  }, []);

  const handleFileSelect = (selectedFile: File) => {
    setFile(selectedFile);
    setFilePreview(URL.createObjectURL(selectedFile));
    setMissingVideoName(null);
    setStatus(ProcessingStatus.IDLE);
    setResult(null);
    setError(null);
    setCurrentTime(0);
  };

  const handleReset = () => {
    setFile(null);
    setFilePreview(null);
    setMissingVideoName(null);
    setStatus(ProcessingStatus.IDLE);
    setResult(null);
    setError(null);
    setCurrentTime(0);
    if (filePreview) URL.revokeObjectURL(filePreview);
  };

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      setCurrentTime(videoRef.current.currentTime);
    }
  };

  const handleSeek = (time: number) => {
    if (videoRef.current) {
      videoRef.current.currentTime = time;
      videoRef.current.play();
    }
  };

  const handleTranscriptUpdate = (updatedData: TranscriptResult) => {
    setResult(updatedData);
  };

  const toggleFullscreen = () => {
    if (!playerContainerRef.current) return;

    if (!document.fullscreenElement) {
      playerContainerRef.current.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable fullscreen: ${err.message}`);
      });
    } else {
      document.exitFullscreen();
    }
  };

  const handleSaveProject = () => {
    if (!result) return;

    const projectData: SavedProject = {
      version: "1.0",
      createdAt: new Date().toISOString(),
      fileName: file ? file.name : (missingVideoName || "video"),
      targetLang: targetLang,
      transcriptResult: result
    };

    const fileName = `tubescribe_project_${new Date().toISOString().slice(0, 10)}.json`;
    downloadJson(projectData, fileName);
  };

  const handleLoadProject = async (projectFile: File) => {
    try {
      const data: SavedProject = await readJsonFile(projectFile);

      // Basic validation
      if (!data.transcriptResult || !data.transcriptResult.segments) {
        throw new Error("Invalid project file structure");
      }

      setResult(data.transcriptResult);
      setTargetLang(data.targetLang || 'my');
      setMissingVideoName(data.fileName || "Unknown Video");

      // Reset video state since we can't load the local path
      if (filePreview) URL.revokeObjectURL(filePreview);
      setFile(null);
      setFilePreview(null);

      setStatus(ProcessingStatus.COMPLETED);
    } catch (err: any) {
      setError("Failed to load project file: " + err.message);
    }
  };

  const handleReuploadVideo = (uploadedFile: File) => {
    setFile(uploadedFile);
    setFilePreview(URL.createObjectURL(uploadedFile));
    setMissingVideoName(null);
    // Status stays COMPLETED, we just added the video back
  };

  const processVideo = async () => {
    if (!file) return;

    setStatus(ProcessingStatus.UPLOADING);
    setError(null);

    try {
      // Step 1: Convert to Base64
      setStatus(ProcessingStatus.ANALYZING);
      const base64Data = await fileToBase64(file);

      const targetLangName = SUPPORTED_LANGUAGES.find(l => l.code === targetLang)?.name || 'Burmese';

      // Step 2: Send to Gemini
      const data = await generateTranscript(base64Data, file.type, targetLangName);

      setResult(data);
      setStatus(ProcessingStatus.COMPLETED);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An error occurred while processing the video.");
      setStatus(ProcessingStatus.ERROR);
    }
  };

  return (
    <div className="min-h-screen bg-[#0f0f0f] text-white selection:bg-red-500/30">
      {/* Navbar */}
      <nav className="border-b border-zinc-800 bg-[#0f0f0f]/80 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3 cursor-pointer" onClick={handleReset}>
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-red-600 to-red-500 flex items-center justify-center">
              <Bot className="w-5 h-5 text-white" />
            </div>
            <span className="font-bold text-xl tracking-tight">TubeScribe</span>
          </div>
          <div className="flex items-center space-x-4">
             <a href="https://ai.google.dev" target="_blank" rel="noreferrer" className="text-xs font-medium text-zinc-500 hover:text-zinc-300 transition-colors">
               Powered by Gemini 2.0
             </a>
          </div>
        </div>
      </nav>

      <main className="max-w-[1600px] mx-auto px-4 py-8">

        {/* Header / Intro - Hide when Completed to save space */}
        {status !== ProcessingStatus.COMPLETED && (
          <div className="flex flex-col items-center justify-center space-y-8 mb-12 py-10">
             <div className="text-center space-y-4 max-w-2xl">
               <h1 className="text-4xl md:text-5xl font-bold bg-clip-text text-transparent bg-gradient-to-b from-white to-zinc-400">
                 Video to Burmese Transcript
               </h1>
               <p className="text-zinc-400 text-lg">
                 Upload any video, and our AI will transcribe the audio and translate it into Burmese (or your language of choice) instantly.
               </p>
             </div>
          </div>
        )}

        {/* Main Content */}
        {!file && !result ? (
          <div className="max-w-5xl mx-auto">
            <FileUpload 
              onFileSelect={handleFileSelect} 
              onLoadProject={handleLoadProject}
            />
            {error && (
              <div className="mt-4 p-4 bg-red-500/10 border border-red-500/20 text-red-200 rounded-xl text-center">
                {error}
              </div>
            )}
          </div>
        ) : (
          <div className="animate-in fade-in zoom-in-95 duration-300">

            {/* COMPLETED VIEW - Split Screen */}
            {status === ProcessingStatus.COMPLETED && result ? (
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Left Column: Video Player OR Missing Video Prompt */}
                <div className="lg:col-span-1 space-y-4">
                   <div className="lg:sticky lg:top-24 space-y-4">

                      {/* Video Player exists */}
                      {filePreview ? (
                        <>
                          {/* Container for Fullscreen */}
                          <div 
                            ref={playerContainerRef} 
                            className={`rounded-2xl overflow-hidden border border-zinc-800 bg-black shadow-2xl relative group
                              ${isFullscreen ? 'flex flex-col bg-black h-screen w-screen fixed top-0 left-0 z-50' : ''}`}
                          >
                            {/* Video Part */}
                            <div className={`${isFullscreen ? 'flex-1 min-h-0 flex items-center justify-center bg-black' : 'w-full'}`}>
                               <video
                                  ref={videoRef}
                                  src={filePreview || ""}
                                  controls
                                  className={`${isFullscreen ? 'h-full w-full object-contain' : 'w-full aspect-video object-contain'}`}
                                  onTimeUpdate={handleTimeUpdate}
                                />
                            </div>

                            {/* Custom Fullscreen Toggle - Only show when NOT fullscreen to trigger our custom mode */}
                            {!isFullscreen && (
                              <button 
                                onClick={toggleFullscreen}
                                className="absolute bottom-16 right-4 p-2 bg-black/60 rounded-lg text-white opacity-0 group-hover:opacity-100 transition-opacity z-10 hover:bg-black/80 hidden md:block"
                                title="Fullscreen with Transcript"
                              >
                                <Maximize2 className="w-5 h-5" />
                              </button>
                            )}

                            {/* Fullscreen Overlay for Transcript - Now at Bottom */}
                            {isFullscreen && (
                              <div className="h-[35vh] min-h-[200px] bg-zinc-900 border-t border-zinc-700 flex flex-col">
                                 <div className="flex justify-between items-center p-2 px-4 bg-black/40 border-b border-zinc-800">
                                   <h3 className="text-zinc-400 text-xs font-medium uppercase tracking-wider">Transcript</h3>
                                   <button 
                                     onClick={toggleFullscreen} 
                                     className="text-zinc-400 hover:text-white flex items-center space-x-1 text-xs"
                                   >
                                     <Maximize2 className="w-3 h-3" />
                                     <span>Exit Fullscreen</span>
                                   </button>
                                 </div>
                                 <div className="flex-1 overflow-hidden">
                                   <TranscriptDisplay 
                                      data={result} 
                                      currentTime={currentTime}
                                      onSeek={handleSeek}
                                      onUpdate={handleTranscriptUpdate}
                                      overlayMode={true}
                                   />
                                 </div>
                              </div>
                            )}
                          </div>

                          {/* Metadata below video (only when not fullscreen) */}
                          {!isFullscreen && (
                            <div className="bg-zinc-900/50 p-5 rounded-2xl border border-zinc-800 backdrop-blur-sm">
                              <h3 className="font-medium text-white truncate text-lg">{file?.name}</h3>
                              <div className="flex items-center justify-between mt-2 text-sm text-zinc-400">
                                <span>{file ? formatFileSize(file.size) : 'Unknown size'}</span>
                                <span className="px-2 py-0.5 rounded bg-zinc-800 text-zinc-300 text-xs border border-zinc-700">
                                   {file?.type.split('/')[1].toUpperCase() || 'VIDEO'}
                                </span>
                              </div>
                            </div>
                          )}
                        </>
                      ) : (
                        /* Missing Video Prompt */
                        <div className="rounded-2xl border-2 border-dashed border-zinc-700 bg-zinc-900/30 p-8 text-center space-y-4 flex flex-col items-center justify-center min-h-[300px]">
                           <div className="w-16 h-16 rounded-full bg-zinc-800 flex items-center justify-center">
                             <Upload className="w-8 h-8 text-zinc-400" />
                           </div>
                           <div>
                             <h3 className="text-xl font-bold text-white mb-2">Video Source Missing</h3>
                             <p className="text-zinc-400 text-sm mb-4">
                               Project loaded, but the video file cannot be restored automatically for security reasons.
                             </p>
                             <div className="bg-zinc-800 p-3 rounded-lg text-sm text-zinc-300 mb-4 inline-block">
                               Expected: <span className="font-mono text-white">{missingVideoName}</span>
                             </div>
                             <p className="text-zinc-500 text-xs mb-4">
                               Upload the video file to sync with the transcript.
                             </p>
                             <input 
                               type="file" 
                               id="reuploadInput" 
                               className="hidden" 
                               accept="video/*,audio/*"
                               onChange={(e) => {
                                 if (e.target.files && e.target.files.length > 0) {
                                   handleReuploadVideo(e.target.files[0]);
                                 }
                               }}
                             />
                             <button 
                               onClick={() => document.getElementById('reuploadInput')?.click()}
                               className="px-6 py-2 bg-red-600 hover:bg-red-500 text-white rounded-xl font-medium transition-colors"
                             >
                               Upload Video
                             </button>
                           </div>
                        </div>
                      )}

                      {!isFullscreen && (
                        <button 
                          onClick={handleReset}
                          className="w-full p-3 rounded-xl bg-zinc-800 hover:bg-zinc-700 text-zinc-300 hover:text-white transition-all flex items-center justify-center space-x-2 text-sm font-medium border border-zinc-700/50 hover:border-zinc-600"
                        >
                          <ChevronLeft className="w-4 h-4" />
                          <span>Process Another Video</span>
                        </button>
                      )}
                   </div>
                </div>

                {/* Right Column: Transcript */}
                <div className="lg:col-span-2 lg:h-[calc(100vh-8rem)] lg:sticky lg:top-24 flex flex-col">
                   <TranscriptDisplay 
                      data={result} 
                      currentTime={currentTime}
                      onSeek={handleSeek}
                      onSave={handleSaveProject}
                      onUpdate={handleTranscriptUpdate}
                   />
                </div>
              </div>
            ) : (
              // ANALYZING / SETUP VIEW
              <div className="max-w-5xl mx-auto space-y-8">
                {/* Toolbar */}
                <div className="flex flex-col md:flex-row items-center justify-between bg-zinc-900/50 p-4 rounded-2xl border border-zinc-800 gap-4">
                   <div className="flex items-center space-x-4 w-full md:w-auto">
                      <div className="relative w-16 h-16 bg-black rounded-lg overflow-hidden flex-shrink-0 border border-zinc-800 group">
                        <video src={filePreview || ""} className="w-full h-full object-cover opacity-60" />
                        <PlayCircle className="absolute inset-0 m-auto w-6 h-6 text-white/80" />
                      </div>
                      <div className="min-w-0">
                        <h3 className="font-medium text-white truncate max-w-[200px]">{file?.name}</h3>
                        <p className="text-xs text-zinc-500">{file ? formatFileSize(file.size) : ''}</p>
                      </div>
                   </div>

                   <div className="flex items-center space-x-4 w-full md:w-auto">
                      <div className="flex-1 md:w-64">
                         <LanguageSelector 
                           selectedCode={targetLang} 
                           onSelect={setTargetLang} 
                           disabled={status === ProcessingStatus.ANALYZING || status === ProcessingStatus.UPLOADING}
                         />
                      </div>

                      {status === ProcessingStatus.IDLE || status === ProcessingStatus.ERROR ? (
                        <div className="flex space-x-2 pt-6">
                          <button 
                            onClick={handleReset}
                            className="p-3 rounded-xl bg-zinc-800 hover:bg-zinc-700 text-zinc-300 transition-colors"
                            title="Upload new file"
                          >
                            <RefreshCw className="w-5 h-5" />
                          </button>
                          <button 
                            onClick={processVideo}
                            className="flex-1 px-6 py-3 bg-red-600 hover:bg-red-500 text-white font-medium rounded-xl transition-all shadow-lg shadow-red-900/20 flex items-center justify-center space-x-2"
                          >
                            <Sparkles className="w-5 h-5" />
                            <span>Generate Transcript</span>
                          </button>
                        </div>
                      ) : null}
                   </div>
                </div>

                {/* Status Display */}
                {(status === ProcessingStatus.ANALYZING || status === ProcessingStatus.UPLOADING) && (
                  <div className="py-20 flex flex-col items-center justify-center space-y-6 text-center">
                    <div className="relative">
                      <div className="absolute inset-0 bg-red-500/20 blur-xl rounded-full animate-pulse"></div>
                      <Loader2 className="w-16 h-16 text-red-500 animate-spin relative z-10" />
                    </div>
                    <div className="space-y-2">
                       <h3 className="text-2xl font-semibold text-white">
                          {status === ProcessingStatus.UPLOADING ? "Preparing Video..." : "AI Analyzing Audio..."}
                       </h3>
                       <p className="text-zinc-400 max-w-md mx-auto">
                         Gemini is listening to the audio, transcribing speech, and translating it to {SUPPORTED_LANGUAGES.find(l => l.code === targetLang)?.name}. This may take a moment depending on the video length.
                       </p>
                    </div>
                  </div>
                )}

                {/* Error Display */}
                {status === ProcessingStatus.ERROR && (
                  <div className="bg-red-500/10 border border-red-500/20 rounded-2xl p-6 flex items-start space-x-4">
                     <AlertTriangle className="w-6 h-6 text-red-500 flex-shrink-0" />
                     <div>
                       <h3 className="text-red-200 font-medium">Processing Error</h3>
                       <p className="text-red-200/60 text-sm mt-1">{error}</p>
                       <p className="text-red-200/40 text-xs mt-2">Try a shorter video or check your API key quota.</p>
                     </div>
                  </div>
                )}
              </div>
            )}

          </div>
        )}
      </main>

      <footer className="border-t border-zinc-900 mt-20 py-8 text-center text-zinc-600 text-sm">
        <p>&copy; {new Date().getFullYear()} TubeScribe. Built with React & Gemini 2.0 Flash.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { TranscriptResult, TranscriptSegment } from '../types';
import { Copy, Check, Download, Clock, Play, Save, Edit2, X, Maximize2, Link } from 'lucide-react';

interface TranscriptDisplayProps {
  data: TranscriptResult;
  currentTime?: number;
  onSeek?: (time: number) => void;
  onSave?: () => void;
  onUpdate?: (updatedData: TranscriptResult) => void;
  overlayMode?: boolean;
}

const parseTimestamp = (timeStr: string): number => {
  if (!timeStr) return 0;
  const parts = timeStr.split(':').map(Number);
  if (parts.some(isNaN)) return NaN;
  if (parts.length === 2) return parts[0] * 60 + parts[1];
  if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
  return 0;
};

const formatTimestamp = (totalSeconds: number): string => {
  if (isNaN(totalSeconds) || totalSeconds < 0) return "00:00";
  const h = Math.floor(totalSeconds / 3600);
  const m = Math.floor((totalSeconds % 3600) / 60);
  const s = Math.floor(totalSeconds % 60);
  if (h > 0) {
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  }
  return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
};

const TranscriptDisplay: React.FC<TranscriptDisplayProps> = ({ 
  data, 
  currentTime = 0, 
  onSeek,
  onSave,
  onUpdate,
  overlayMode = false
}) => {
  const [copiedOriginal, setCopiedOriginal] = useState(false);
  const [copiedTranslated, setCopiedTranslated] = useState(false);
  const [autoScroll, setAutoScroll] = useState(true);
  const [isEditing, setIsEditing] = useState(false);
  const [localSegments, setLocalSegments] = useState<TranscriptSegment[]>(data.segments);
  const [shiftTimestamps, setShiftTimestamps] = useState(true);
  const [focusTime, setFocusTime] = useState<number | null>(null);

  const activeSegmentRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Sync local state when data changes externally (unless we are in the middle of editing)
  useEffect(() => {
    if (!isEditing) {
      setLocalSegments(data.segments);
    }
  }, [data, isEditing]);

  // Find active segment
  const activeIndex = localSegments.findIndex((seg, index) => {
    const start = parseTimestamp(seg.startTime);
    const nextSeg = localSegments[index + 1];
    const end = nextSeg ? parseTimestamp(nextSeg.startTime) : parseTimestamp(seg.endTime);
    return currentTime >= start && currentTime < end;
  });

  // Auto-focus on Edit Mode
  useEffect(() => {
    if (isEditing && activeIndex !== -1) {
      setTimeout(() => {
        const el = document.getElementById(`original-text-${activeIndex}`);
        if (el) {
          el.focus();
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 100);
    }
  }, [isEditing]); // Only run when entering edit mode

  // Auto-scroll effect
  useEffect(() => {
    if (autoScroll && activeIndex !== -1 && activeSegmentRef.current && !isEditing) {
      activeSegmentRef.current.scrollIntoView({ 
        behavior: 'smooth', 
        block: 'center' 
      });
    }
  }, [activeIndex, autoScroll, isEditing]);

  const handleSegmentChange = (index: number, field: keyof TranscriptSegment, value: string) => {
    const newSegments = [...localSegments];
    newSegments[index] = { ...newSegments[index], [field]: value };
    setLocalSegments(newSegments);
  };

  const handleTimestampFocus = (timeStr: string) => {
    const time = parseTimestamp(timeStr);
    if (!isNaN(time)) {
      setFocusTime(time);
    }
  };

  const handleTimestampBlur = (index: number, field: 'startTime' | 'endTime', value: string) => {
    if (focusTime === null) return;

    const newTime = parseTimestamp(value);

    // If invalid format, revert to original focus time
    if (isNaN(newTime)) {
      const newSegments = [...localSegments];
      newSegments[index] = { ...newSegments[index], [field]: formatTimestamp(focusTime) };
      setLocalSegments(newSegments);
      setFocusTime(null);
      return;
    }

    const delta = newTime - focusTime;

    // If no change, do nothing
    if (delta === 0) {
      setFocusTime(null);
      return;
    }

    // Apply updates
    const newSegments = [...localSegments];

    // Format the current field correctly
    newSegments[index] = { ...newSegments[index], [field]: formatTimestamp(newTime) };

    if (shiftTimestamps) {
      // If editing StartTime: Shift EndTime of current + Start/End of all subsequent
      if (field === 'startTime') {
        const currentEnd = parseTimestamp(newSegments[index].endTime);
        if (!isNaN(currentEnd)) {
           newSegments[index].endTime = formatTimestamp(currentEnd + delta);
        }
      }

      // Shift all subsequent segments
      for (let i = index + 1; i < newSegments.length; i++) {
        const sStart = parseTimestamp(newSegments[i].startTime);
        const sEnd = parseTimestamp(newSegments[i].endTime);

        if (!isNaN(sStart)) newSegments[i].startTime = formatTimestamp(sStart + delta);
        if (!isNaN(sEnd)) newSegments[i].endTime = formatTimestamp(sEnd + delta);
      }
    }

    setLocalSegments(newSegments);
    setFocusTime(null);
  };

  const saveEdits = () => {
    if (onUpdate) {
      onUpdate({ ...data, segments: localSegments });
    }
    setIsEditing(false);
  };

  const cancelEdits = () => {
    setLocalSegments(data.segments);
    setIsEditing(false);
  };

  const getFullText = (isOriginal: boolean) => {
    return localSegments
      .map(s => isOriginal ? s.originalText : s.translatedText)
      .join('\n');
  };

  const copyToClipboard = async (isOriginal: boolean) => {
    try {
      const text = getFullText(isOriginal);
      await navigator.clipboard.writeText(text);
      if (isOriginal) {
        setCopiedOriginal(true);
        setTimeout(() => setCopiedOriginal(false), 2000);
      } else {
        setCopiedTranslated(true);
        setTimeout(() => setCopiedTranslated(false), 2000);
      }
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  const downloadSRT = () => {
    let srtContent = '';
    localSegments.forEach((segment, index) => {
      const formatTime = (time: string) => {
        const parts = time.split(':');
        if (parts.length === 2) return `00:${time},000`;
        return `${time},000`;
      };
      srtContent += `${index + 1}\n`;
      srtContent += `${formatTime(segment.startTime)} --> ${formatTime(segment.endTime)}\n`;
      srtContent += `${segment.originalText}\n`;
      srtContent += `${segment.translatedText}\n\n`;
    });

    const blob = new Blob([srtContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `transcript_${data.originalLanguage}_to_${data.translatedLanguage}.srt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className={`w-full flex flex-col h-full bg-[#0f0f0f] ${overlayMode ? 'text-sm' : ''}`}>
      {/* Header Toolbar - Fixed Top */}
      <div className={`flex flex-wrap justify-between items-center gap-4 flex-shrink-0 mb-4 bg-[#0f0f0f] z-30 py-2 ${overlayMode ? 'sticky top-0 px-2' : 'sticky top-16'}`}>
        {!overlayMode && <h2 className="text-xl font-bold text-white">Transcript</h2>}

        <div className="flex flex-wrap gap-2 ml-auto items-center">
          {/* Edit Controls */}
          {onUpdate && !isEditing && (
            <button
              onClick={() => setIsEditing(true)}
              className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-zinc-800 hover:bg-zinc-700 text-xs font-medium text-zinc-300 transition-colors border border-zinc-700"
            >
              <Edit2 className="w-3 h-3" />
              <span className="hidden sm:inline">Edit</span>
            </button>
          )}

          {isEditing && (
            <div className="flex items-center space-x-2 bg-zinc-900 rounded-lg p-1 border border-zinc-700 mr-2">
              <label className="flex items-center space-x-2 px-2 py-1 cursor-pointer">
                <input 
                  type="checkbox" 
                  checked={shiftTimestamps} 
                  onChange={(e) => setShiftTimestamps(e.target.checked)}
                  className="rounded bg-zinc-700 border-zinc-600 text-red-600 focus:ring-red-500/50"
                />
                <span className="text-xs text-zinc-300 whitespace-nowrap" title="Automatically adjust subsequent timestamps when you edit a time">Shift Following</span>
              </label>
            </div>
          )}

          {isEditing && (
            <>
              <button
