            </div>
            <span className="font-bold text-xl tracking-tight">TubeScribe</span>
          </div>
          <div className="flex items-center space-x-4">
             <a href="https://ai.google.dev" target="_blank" rel="noreferrer" className="text-xs font-medium text-zinc-500 hover:text-zinc-300 transition-colors">
               Powered by Gemini 2.0
             </a>
          </div>
        </div>
      </nav>

      <main className="max-w-[1600px] mx-auto px-4 py-8">

        {/* Header / Intro - Hide when Completed to save space */}
        {status !== ProcessingStatus.COMPLETED && (
          <div className="flex flex-col items-center justify-center space-y-8 mb-12 py-10">
             <div className="text-center space-y-4 max-w-2xl">
               <h1 className="text-4xl md:text-5xl font-bold bg-clip-text text-transparent bg-gradient-to-b from-white to-zinc-400">
