  const [status, setStatus] = useState<ProcessingStatus>(ProcessingStatus.IDLE);
  const [targetLang, setTargetLang] = useState<string>('my'); // Default to Burmese (my)
  const [result, setResult] = useState<TranscriptResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [currentTime, setCurrentTime] = useState(0);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [transcriptHeight, setTranscriptHeight] = useState(35); // Percentage height for transcript in fullscreen

  // Split Pane State
  const [leftPaneWidth, setLeftPaneWidth] = useState(35); // Default percentage for video column
  const [isResizingSplit, setIsResizingSplit] = useState(false);
  const splitPaneRef = useRef<HTMLDivElement>(null);

  // Save Modal State
  const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);

  // State for loaded projects where video is missing
  const [missingVideoName, setMissingVideoName] = useState<string | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const playerContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  // Fullscreen event listeners
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };

    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => {
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
    };
  }, []);

  // Resizing logic for fullscreen vertical resize
  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDraggingRef.current) return;

      const windowHeight = window.innerHeight;
      const mouseY = e.clientY;
      // Calculate height from bottom
      const newHeightPercentage = ((windowHeight - mouseY) / windowHeight) * 100;

      // Clamp between 20% and 80%
      const clampedHeight = Math.max(20, Math.min(80, newHeightPercentage));
      setTranscriptHeight(clampedHeight);
    };

    const handleMouseUp = () => {
      if (isDraggingRef.current) {
        isDraggingRef.current = false;
        document.body.style.userSelect = '';
        document.body.style.cursor = '';
      }
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  const startResize = (e: React.MouseEvent) => {
    e.preventDefault();
    isDraggingRef.current = true;
    document.body.style.userSelect = 'none';
    document.body.style.cursor = 'row-resize';
  };

  // Resizing logic for horizontal split pane
  useEffect(() => {
    const handleSplitMouseMove = (e: MouseEvent) => {
      if (!isResizingSplit || !splitPaneRef.current) return;

      const containerRect = splitPaneRef.current.getBoundingClientRect();
      // Calculate percentage relative to container width
      let newWidth = ((e.clientX - containerRect.left) / containerRect.width) * 100;

      // Clamp between 20% and 70%
      newWidth = Math.max(20, Math.min(70, newWidth));

      setLeftPaneWidth(newWidth);
    };

    const handleSplitMouseUp = () => {
      if (isResizingSplit) {
        setIsResizingSplit(false);
        document.body.style.userSelect = '';
        document.body.style.cursor = '';
      }
    };

    if (isResizingSplit) {
      document.addEventListener('mousemove', handleSplitMouseMove);
      document.addEventListener('mouseup', handleSplitMouseUp);
    }

    return () => {
      document.removeEventListener('mousemove', handleSplitMouseMove);
      document.removeEventListener('mouseup', handleSplitMouseUp);
    };
  }, [isResizingSplit]);

  const startSplitResize = (e: React.MouseEvent) => {
    e.preventDefault();
    setIsResizingSplit(true);
    document.body.style.userSelect = 'none';
    document.body.style.cursor = 'col-resize';
  };

  const handleFileSelect = (selectedFile: File) => {
    setFile(selectedFile);
    setFilePreview(URL.createObjectURL(selectedFile));
    setMissingVideoName(null);
    setStatus(ProcessingStatus.IDLE);
    setResult(null);
    setError(null);
    setCurrentTime(0);
  };

  const handleReset = () => {
    setFile(null);
    setFilePreview(null);
    setMissingVideoName(null);
    setStatus(ProcessingStatus.IDLE);
    setResult(null);
    setError(null);
    setCurrentTime(0);
    if (filePreview) URL.revokeObjectURL(filePreview);
  };

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      setCurrentTime(videoRef.current.currentTime);
    }
  };

  const handleSeek = (time: number) => {
    if (videoRef.current) {
      videoRef.current.currentTime = time;
      videoRef.current.play();
    }
  };

  const handleTranscriptUpdate = (updatedData: TranscriptResult) => {
    setResult(updatedData);
  };

  const toggleFullscreen = () => {
    if (!playerContainerRef.current) return;

    if (!document.fullscreenElement) {
      playerContainerRef.current.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable fullscreen: ${err.message}`);
      });
    } else {
      document.exitFullscreen();
    }
  };

  const openSaveModal = () => {
    setIsSaveModalOpen(true);
  };

  const handleConfirmSave = (fileName: string, videoName: string) => {
    if (!result) return;

    // Ensure filename ends with .json
    const finalFileName = fileName.toLowerCase().endsWith('.json') ? fileName : `${fileName}.json`;

    const projectData: SavedProject = {
      version: "1.0",
      createdAt: new Date().toISOString(),
      fileName: videoName, // Save the video location/name input by user
      targetLang: targetLang,
      transcriptResult: result
    };

    downloadJson(projectData, finalFileName);
    setIsSaveModalOpen(false);
  };

  const handleLoadProject = async (projectFile: File) => {
    try {
      const data: SavedProject = await readJsonFile(projectFile);

      // Basic validation
      if (!data.transcriptResult || !data.transcriptResult.segments) {
        throw new Error("Invalid project file structure");
      }

      setResult(data.transcriptResult);
      setTargetLang(data.targetLang || 'my');
      setMissingVideoName(data.fileName || "Unknown Video");

      // Reset video state since we can't load the local path
      if (filePreview) URL.revokeObjectURL(filePreview);
      setFile(null);
      setFilePreview(null);

      setStatus(ProcessingStatus.COMPLETED);
    } catch (err: any) {
      setError("Failed to load project file: " + err.message);
    }
  };

  const handleReuploadVideo = (uploadedFile: File) => {
    setFile(uploadedFile);
    setFilePreview(URL.createObjectURL(uploadedFile));
    setMissingVideoName(null);
    // Status stays COMPLETED, we just added the video back
  };

  const processVideo = async () => {
    if (!file) return;

    setStatus(ProcessingStatus.UPLOADING);
    setError(null);

    try {
      // Step 1: Convert to Base64
      setStatus(ProcessingStatus.ANALYZING);
      const base64Data = await fileToBase64(file);

      const targetLangName = SUPPORTED_LANGUAGES.find(l => l.code === targetLang)?.name || 'Burmese';

      // Step 2: Send to Gemini
      const data = await generateTranscript(base64Data, file.type, targetLangName);

      setResult(data);
      setStatus(ProcessingStatus.COMPLETED);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "An error occurred while processing the video.");
      setStatus(ProcessingStatus.ERROR);
    }
  };

  const getDefaultSaveName = () => {
    return `tubescribe_project_${new Date().toISOString().slice(0, 10)}.json`;
  };

  const getDefaultVideoName = () => {
    return file ? file.name : (missingVideoName || "video.mp4");
  };

  return (
    <div className="min-h-screen bg-[#0f0f0f] text-white selection:bg-red-500/30">
      <SaveModal 
        isOpen={isSaveModalOpen}
        onClose={() => setIsSaveModalOpen(false)}
        onConfirm={handleConfirmSave}
        defaultFileName={getDefaultSaveName()}
        defaultVideoName={getDefaultVideoName()}
      />

      {/* Navbar */}
      <nav className="border-b border-zinc-800 bg-[#0f0f0f]/80 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-[1920px] mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center space-x-3 cursor-pointer" onClick={handleReset}>
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-red-600 to-red-500 flex items-center justify-center">
              <Bot className="w-5 h-5 text-white" />
            </div>
            <span className="font-bold text-xl tracking-tight">TubeScribe</span>
          </div>
          <div className="flex items-center space-x-4">
             <a href="https://ai.google.dev" target="_blank" rel="noreferrer" className="text-xs font-medium text-zinc-500 hover:text-zinc-300 transition-colors">
               Powered by Gemini 2.0
             </a>
          </div>
        </div>
      </nav>

      <main className="max-w-[1920px] mx-auto px-4 py-6">

        {/* Header / Intro - Hide when Completed to save space */}
        {status !== ProcessingStatus.COMPLETED && (
          <div className="flex flex-col items-center justify-center space-y-8 mb-12 py-10">
             <div className="text-center space-y-4 max-w-2xl">
               <h1 className="text-4xl md:text-5xl font-bold bg-clip-text text-transparent bg-gradient-to-b from-white to-zinc-400">
                 Video to Burmese Transcript
               </h1>
               <p className="text-zinc-400 text-lg">
                 Upload any video, and our AI will transcribe the audio and translate it into Burmese (or your language of choice) instantly.
               </p>
             </div>
          </div>
        )}

        {/* Main Content */}
        {!file && !result ? (
          <div className="max-w-5xl mx-auto">
            <FileUpload 
              onFileSelect={handleFileSelect} 
              onLoadProject={handleLoadProject}
            />
            {error && (
              <div className="mt-4 p-4 bg-red-500/10 border border-red-500/20 text-red-200 rounded-xl text-center">
                {error}
              </div>
            )}
          </div>
        ) : (
          <div className="animate-in fade-in zoom-in-95 duration-300">

            {/* COMPLETED VIEW - Split Screen */}
            {status === ProcessingStatus.COMPLETED && result ? (
              <div 
                ref={splitPaneRef} 
                className="flex flex-col lg:flex-row gap-8 lg:gap-0"
              >
                {/* Left Column: Video Player OR Missing Video Prompt */}
                <div 
                  className="lg:shrink-0 w-full"
                  style={{ width: typeof window !== 'undefined' && window.innerWidth >= 1024 ? `${leftPaneWidth}%` : '100%' }}
                >
                   <div className="lg:sticky lg:top-24 space-y-4 lg:pr-4">

                      {/* Video Player exists */}
                      {filePreview ? (
                        <>
                          {/* Container for Fullscreen */}
                          <div 
                            ref={playerContainerRef} 
                            className={`rounded-2xl overflow-hidden border border-zinc-800 bg-black shadow-2xl relative group
                              ${isFullscreen ? 'flex flex-col bg-black h-screen w-screen fixed top-0 left-0 z-50' : ''}`}
                          >
                            {/* Video Part */}
                            <div className={`${isFullscreen ? 'flex-1 min-h-0 flex items-center justify-center bg-black' : 'w-full'}`}>
                               <video
                                  ref={videoRef}
                                  src={filePreview || ""}
                                  controls
                                  className={`${isFullscreen ? 'h-full w-full object-contain' : 'w-full aspect-video object-contain'}`}
                                  onTimeUpdate={handleTimeUpdate}
                                />
                            </div>

                            {/* Custom Fullscreen Toggle - Only show when NOT fullscreen to trigger our custom mode */}
                            {!isFullscreen && (
                              <button 
                                onClick={toggleFullscreen}
                                className="absolute bottom-16 right-4 p-2 bg-black/60 rounded-lg text-white opacity-0 group-hover:opacity-100 transition-opacity z-10 hover:bg-black/80 hidden md:block"
                                title="Fullscreen with Transcript"
                              >
                                <Maximize2 className="w-5 h-5" />
                              </button>
                            )}

                            {/* Resizer Handle (Only in fullscreen) */}
                            {isFullscreen && (
                              <div 
                                className="h-4 bg-zinc-900 hover:bg-zinc-700 cursor-row-resize flex items-center justify-center z-30 border-t border-b border-zinc-800 flex-shrink-0 transition-colors"
                                onMouseDown={startResize}
                                title="Drag to resize"
                              >
                                <div className="w-12 h-1 bg-zinc-600 rounded-full" />
                              </div>
                            )}

                            {/* Fullscreen Overlay for Transcript - Now at Bottom with dynamic height */}
                            {isFullscreen && (
                              <div 
                                style={{ height: `${transcriptHeight}vh` }}
                                className="bg-zinc-900 flex flex-col min-h-0"
                              >
                                 <div className="flex justify-between items-center p-2 px-4 bg-black/40 border-b border-zinc-800 flex-shrink-0">
                                   <h3 className="text-zinc-400 text-xs font-medium uppercase tracking-wider">Transcript</h3>
                                   <button 
                                     onClick={toggleFullscreen} 
                                     className="text-zinc-400 hover:text-white flex items-center space-x-1 text-xs"
                                   >
                                     <Maximize2 className="w-3 h-3" />
                                     <span>Exit Fullscreen</span>
                                   </button>
                                 </div>
                                 <div className="flex-1 overflow-hidden">
                                   <TranscriptDisplay 
                                      data={result} 
                                      currentTime={currentTime}
                                      onSeek={handleSeek}
                                      onUpdate={handleTranscriptUpdate}
                                      overlayMode={true}
                                   />
                                 </div>
                              </div>
                            )}
                          </div>

                          {/* Metadata below video (only when not fullscreen) */}
                          {!isFullscreen && (
                            <div className="bg-zinc-900/50 p-5 rounded-2xl border border-zinc-800 backdrop-blur-sm">
                              <h3 className="font-medium text-white truncate text-lg">{file?.name}</h3>
                              <div className="flex items-center justify-between mt-2 text-sm text-zinc-400">
                                <span>{file ? formatFileSize(file.size) : 'Unknown size'}</span>
                                <span className="px-2 py-0.5 rounded bg-zinc-800 text-zinc-300 text-xs border border-zinc-700">
                                   {file?.type.split('/')[1].toUpperCase() || 'VIDEO'}
                                </span>
                              </div>
                            </div>
                          )}
                        </>
                      ) : (
                        /* Missing Video Prompt */
                        <div className="rounded-2xl border-2 border-dashed border-zinc-700 bg-zinc-900/30 p-8 text-center space-y-4 flex flex-col items-center justify-center min-h-[300px]">
                           <div className="w-16 h-16 rounded-full bg-zinc-800 flex items-center justify-center">
                             <Upload className="w-8 h-8 text-zinc-400" />
                           </div>
                           <div>
                             <h3 className="text-xl font-bold text-white mb-2">Video Source Missing</h3>
                             <p className="text-zinc-400 text-sm mb-4">
                               Project loaded, but the video file cannot be restored automatically for security reasons.
                             </p>
                             <div className="bg-zinc-800 p-3 rounded-lg text-sm text-zinc-300 mb-4 inline-block">
                               Expected: <span className="font-mono text-white">{missingVideoName}</span>
                             </div>
                             <p className="text-zinc-500 text-xs mb-4">
                               Upload the video file to sync with the transcript.
                             </p>
                             <input 
                               type="file" 
                               id="reuploadInput" 
                               className="hidden" 
                               accept="video/*,audio/*"
                               onChange={(e) => {
                                 if (e.target.files && e.target.files.length > 0) {
                                   handleReuploadVideo(e.target.files[0]);
                                 }
                               }}
                             />
                             <button 
                               onClick={() => document.getElementById('reuploadInput')?.click()}
                               className="px-6 py-2 bg-red-600 hover:bg-red-500 text-white rounded-xl font-medium transition-colors"
                             >
                               Upload Video
                             </button>
                           </div>
                        </div>
                      )}

                      {!isFullscreen && (
                        <button 
                          onClick={handleReset}
                          className="w-full p-3 rounded-xl bg-zinc-800 hover:bg-zinc-700 text-zinc-300 hover:text-white transition-all flex items-center justify-center space-x-2 text-sm font-medium border border-zinc-700/50 hover:border-zinc-600"
                        >
                          <ChevronLeft className="w-4 h-4" />
                          <span>Process Another Video</span>
                        </button>
                      )}
                   </div>
                </div>

                {/* Resizer Handle (Desktop Only) */}
                <div 
                  className="hidden lg:flex w-6 -ml-3 z-30 cursor-col-resize items-center justify-center group select-none sticky top-[40vh]"
                  onMouseDown={startSplitResize}
                  title="Drag to resize columns"
                >
                   <div className="w-1.5 h-16 bg-zinc-800 rounded-full group-hover:bg-red-500/80 transition-all shadow-lg flex items-center justify-center">
                      <GripVertical className="w-3 h-3 text-zinc-500 group-hover:text-white/80" />
                   </div>
                </div>

                {/* Right Column: Transcript */}
                <div className="flex-1 min-w-0 lg:h-[calc(100vh-8rem)] lg:sticky lg:top-24 flex flex-col lg:pl-1">
                   <TranscriptDisplay 
                      data={result} 
                      currentTime={currentTime}
                      onSeek={handleSeek}
                      onSave={openSaveModal}
                      onUpdate={handleTranscriptUpdate}
                   />
                </div>
              </div>
            ) : (
              // ANALYZING / SETUP VIEW
              <div className="max-w-5xl mx-auto space-y-8">
                {/* Toolbar */}
                <div className="flex flex-col md:flex-row items-center justify-between bg-zinc-900/50 p-4 rounded-2xl border border-zinc-800 gap-4">
                   <div className="flex items-center space-x-4 w-full md:w-auto">
                      <div className="relative w-16 h-16 bg-black rounded-lg overflow-hidden flex-shrink-0 border border-zinc-800 group">
                        <video src={filePreview || ""} className="w-full h-full object-cover opacity-60" />
                        <PlayCircle className="absolute inset-0 m-auto w-6 h-6 text-white/80" />
                      </div>
                      <div className="min-w-0">
                        <h3 className="font-medium text-white truncate max-w-[200px]">{file?.name}</h3>
                        <p className="text-xs text-zinc-500">{file ? formatFileSize(file.size) : ''}</p>
                      </div>
                   </div>

                   <div className="flex items-center space-x-4 w-full md:w-auto">
                      <div className="flex-1 md:w-64">
                         <LanguageSelector 
                           selectedCode={targetLang} 
                           onSelect={setTargetLang} 
                           disabled={status === ProcessingStatus.ANALYZING || status === ProcessingStatus.UPLOADING}
                         />
                      </div>

                      {status === ProcessingStatus.IDLE || status === ProcessingStatus.ERROR ? (
                        <div className="flex space-x-2 pt-6">
                          <button 
                            onClick={handleReset}
                            className="p-3 rounded-xl bg-zinc-800 hover:bg-zinc-700 text-zinc-300 transition-colors"
                            title="Upload new file"
                          >
                            <RefreshCw className="w-5 h-5" />
                          </button>
                          <button 
                            onClick={processVideo}
                            className="flex-1 px-6 py-3 bg-red-600 hover:bg-red-500 text-white font-medium rounded-xl transition-all shadow-lg shadow-red-900/20 flex items-center justify-center space-x-2"
                          >
                            <Sparkles className="w-5 h-5" />
                            <span>Generate Transcript</span>
                          </button>
                        </div>
                      ) : null}
                   </div>
                </div>

                {/* Status Display */}
                {(status === ProcessingStatus.ANALYZING || status === ProcessingStatus.UPLOADING) && (
                  <div className="py-20 flex flex-col items-center justify-center space-y-6 text-center">
                    <div className="relative">
                      <div className="absolute inset-0 bg-red-500/20 blur-xl rounded-full animate-pulse"></div>
                      <Loader2 className="w-16 h-16 text-red-500 animate-spin relative z-10" />
                    </div>
                    <div className="space-y-2">
                       <h3 className="text-2xl font-semibold text-white">
                          {status === ProcessingStatus.UPLOADING ? "Preparing Video..." : "AI Analyzing Audio..."}
                       </h3>
                       <p className="text-zinc-400 max-w-md mx-auto">
                         Gemini is listening to the audio, transcribing speech, and translating it to {SUPPORTED_LANGUAGES.find(l => l.code === targetLang)?.name}. This may take a moment depending on the video length.
                       </p>
                    </div>
                  </div>
                )}

                {/* Error Display */}
                {status === ProcessingStatus.ERROR && (
                  <div className="bg-red-500/10 border border-red-500/20 rounded-2xl p-6 flex items-start space-x-4">
                     <AlertTriangle className="w-6 h-6 text-red-500 flex-shrink-0" />
                     <div>
                       <h3 className="text-red-200 font-medium">Processing Error</h3>
                       <p className="text-red-200/60 text-sm mt-1">{error}</p>
                       <p className="text-red-200/40 text-xs mt-2">Try a shorter video or check your API key quota.</p>
                     </div>
                  </div>
                )}
              </div>
            )}

          </div>
        )}
      </main>

      <footer className="border-t border-zinc-900 mt-20 py-8 text-center text-zinc-600 text-sm">
        <p>&copy; {new Date().getFullYear()} TubeScribe. Built with React & Gemini 2.0 Flash.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { TranscriptResult, TranscriptSegment } from '../types';
import { Copy, Check, Download, Clock, Play, Save, Edit2, X, BookOpen, Pause, FastForward } from 'lucide-react';

interface TranscriptDisplayProps {
  data: TranscriptResult;
  currentTime?: number;
  onSeek?: (time: number) => void;
  onSave?: () => void;
  onUpdate?: (updatedData: TranscriptResult) => void;
  overlayMode?: boolean;
}

const parseTimestamp = (timeStr: string): number => {
  if (!timeStr) return 0;
  const parts = timeStr.split(':').map(Number);
  if (parts.some(isNaN)) return NaN;
  if (parts.length === 2) return parts[0] * 60 + parts[1];
  if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
  return 0;
};

const formatTimestamp = (totalSeconds: number): string => {
  if (isNaN(totalSeconds) || totalSeconds < 0) return "00:00";
  const h = Math.floor(totalSeconds / 3600);
  const m = Math.floor((totalSeconds % 3600) / 60);
  const s = Math.floor(totalSeconds % 60);
  if (h > 0) {
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  }
  return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
};

const TranscriptDisplay: React.FC<TranscriptDisplayProps> = ({ 
  data, 
  currentTime = 0, 
  onSeek,
  onSave,
  onUpdate,
  overlayMode = false
}) => {
  const [copiedOriginal, setCopiedOriginal] = useState(false);
  const [copiedTranslated, setCopiedTranslated] = useState(false);
  const [autoScroll, setAutoScroll] = useState(true);
  const [isEditing, setIsEditing] = useState(false);
  const [localSegments, setLocalSegments] = useState<TranscriptSegment[]>(data.segments);
  const [shiftTimestamps, setShiftTimestamps] = useState(true);
  const [focusTime, setFocusTime] = useState<number | null>(null);

  // Reader Mode State
  const [isReaderMode, setIsReaderMode] = useState(false);
  const [isReaderScrolling, setIsReaderScrolling] = useState(false);
  const [readerSpeed, setReaderSpeed] = useState(1); // 1 = slow, 5 = fast

  const activeSegmentRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Sync local state when data changes externally (unless we are in the middle of editing)
  useEffect(() => {
    if (!isEditing) {
      setLocalSegments(data.segments);
    }
  }, [data, isEditing]);

  // Find active segment
  const activeIndex = localSegments.findIndex((seg, index) => {
    const start = parseTimestamp(seg.startTime);
    const nextSeg = localSegments[index + 1];
    const end = nextSeg ? parseTimestamp(nextSeg.startTime) : parseTimestamp(seg.endTime);
    return currentTime >= start && currentTime < end;
  });

  // Auto-focus on Edit Mode
  useEffect(() => {
    if (isEditing && activeIndex !== -1) {
      setTimeout(() => {
        const el = document.getElementById(`original-text-${activeIndex}`);
        if (el) {
          el.focus();
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 100);
    }
  }, [isEditing]); // Only run when entering edit mode

  // Standard Auto-scroll effect (Sync with video)
  useEffect(() => {
    if (autoScroll && !isReaderMode && activeIndex !== -1 && activeSegmentRef.current && !isEditing) {
      activeSegmentRef.current.scrollIntoView({ 
        behavior: 'smooth', 
        block: 'center' 
      });
    }
  }, [activeIndex, autoScroll, isEditing, isReaderMode]);

  // Reader Mode Teleprompter Scroll
  useEffect(() => {
    let animationFrameId: number;
    let lastTime: number = 0;

    const animateScroll = (timestamp: number) => {
      if (!lastTime) lastTime = timestamp;
      const deltaTime = timestamp - lastTime;

      if (isReaderScrolling && containerRef.current && deltaTime >= 16) { // ~60fps
         // Speed factor: 1 = 0.5px/frame, 10 = 5px/frame
         // Reduced to ~70% of previous 0.3 value (0.21)
         const pxPerFrame = readerSpeed * 0.21;
         containerRef.current.scrollTop += pxPerFrame;
         lastTime = timestamp;
      }

      if (isReaderScrolling) {
        animationFrameId = requestAnimationFrame(animateScroll);
      }
    };

    if (isReaderScrolling) {
      animationFrameId = requestAnimationFrame(animateScroll);
    }

    return () => cancelAnimationFrame(animationFrameId);
  }, [isReaderScrolling, readerSpeed]);

  const handleSegmentChange = (index: number, field: keyof TranscriptSegment, value: string) => {
    const newSegments = [...localSegments];
    newSegments[index] = { ...newSegments[index], [field]: value };
    setLocalSegments(newSegments);
  };

  const handleTimestampFocus = (timeStr: string) => {
    const time = parseTimestamp(timeStr);
    if (!isNaN(time)) {
      setFocusTime(time);
    }
  };

  const handleTimestampBlur = (index: number, field: 'startTime' | 'endTime', value: string) => {
    if (focusTime === null) return;

    const newTime = parseTimestamp(value);

    // If invalid format, revert to original focus time
    if (isNaN(newTime)) {
      const newSegments = [...localSegments];
      newSegments[index] = { ...newSegments[index], [field]: formatTimestamp(focusTime) };
      setLocalSegments(newSegments);
      setFocusTime(null);
      return;
    }

    const delta = newTime - focusTime;

    // If no change, do nothing
    if (delta === 0) {
      setFocusTime(null);
      return;
    }

    // Apply updates
    const newSegments = [...localSegments];

    // Format the current field correctly
    newSegments[index] = { ...newSegments[index], [field]: formatTimestamp(newTime) };

    if (shiftTimestamps) {
      // If editing StartTime: Shift EndTime of current + Start/End of all subsequent
      if (field === 'startTime') {
        const currentEnd = parseTimestamp(newSegments[index].endTime);
        if (!isNaN(currentEnd)) {
           newSegments[index].endTime = formatTimestamp(currentEnd + delta);
        }
      }

      // Shift all subsequent segments
      for (let i = index + 1; i < newSegments.length; i++) {
        const sStart = parseTimestamp(newSegments[i].startTime);
        const sEnd = parseTimestamp(newSegments[i].endTime);

        if (!isNaN(sStart)) newSegments[i].startTime = formatTimestamp(sStart + delta);
        if (!isNaN(sEnd)) newSegments[i].endTime = formatTimestamp(sEnd + delta);
      }
    }

    setLocalSegments(newSegments);
    setFocusTime(null);
  };

  const saveEdits = () => {
    // Filter out segments where both text fields are empty
    const validSegments = localSegments.filter(seg => 
      seg.originalText.trim().length > 0 || seg.translatedText.trim().length > 0
    );

    if (onUpdate) {
      onUpdate({ ...data, segments: validSegments });
    }

    setLocalSegments(validSegments);
    setIsEditing(false);
  };

  const cancelEdits = () => {
    setLocalSegments(data.segments);
    setIsEditing(false);
  };

  const getFullText = (isOriginal: boolean) => {
    return localSegments
      .map(s => isOriginal ? s.originalText : s.translatedText)
      .join('\n');
  };

  const copyToClipboard = async (isOriginal: boolean) => {
    try {
      const text = getFullText(isOriginal);
      await navigator.clipboard.writeText(text);
      if (isOriginal) {
        setCopiedOriginal(true);
        setTimeout(() => setCopiedOriginal(false), 2000);
      } else {
        setCopiedTranslated(true);
        setTimeout(() => setCopiedTranslated(false), 2000);
      }
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  const downloadSRT = () => {
    let srtContent = '';
    localSegments.forEach((segment, index) => {
      const formatTime = (time: string) => {
        const parts = time.split(':');
        if (parts.length === 2) return `00:${time},000`;
        return `${time},000`;
      };
      srtContent += `${index + 1}\n`;
      srtContent += `${formatTime(segment.startTime)} --> ${formatTime(segment.endTime)}\n`;
      srtContent += `${segment.originalText}\n`;
      srtContent += `${segment.translatedText}\n\n`;
    });

    const blob = new Blob([srtContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `transcript_${data.originalLanguage}_to_${data.translatedLanguage}.srt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className={`w-full flex flex-col h-full bg-[#0f0f0f] ${overlayMode ? 'text-sm' : ''}`}>
      {/* Header Toolbar - Fixed Top */}
      <div className={`flex flex-wrap justify-between items-center gap-4 flex-shrink-0 mb-4 bg-[#0f0f0f] z-30 py-2 ${overlayMode ? 'sticky top-0 px-2' : 'sticky top-16'}`}>
        {!overlayMode && <h2 className="text-xl font-bold text-white">Transcript</h2>}

        <div className="flex flex-wrap gap-2 ml-auto items-center">

          {/* Reader Mode Toggle */}
          {!isEditing && (
            <button
              onClick={() => {
                setIsReaderMode(!isReaderMode);
                setIsReaderScrolling(false); // Stop auto scroll when switching modes
              }}
              className={`flex items-center space-x-2 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors border
                ${isReaderMode 
                  ? 'bg-amber-600/20 border-amber-500/50 text-amber-400 hover:bg-amber-600/30' 
                  : 'bg-zinc-800 border-zinc-700 text-zinc-400 hover:bg-zinc-700'
                }`}
            >
              <BookOpen className="w-3 h-3" />
              <span className="hidden sm:inline">Reader Mode</span>
            </button>
          )}

          {/* Reader Mode Controls */}
          {isReaderMode && (
             <div className="flex items-center space-x-2 bg-zinc-900 rounded-lg p-1 border border-zinc-700 mr-2">
                <button
                  onClick={() => setIsReaderScrolling(!isReaderScrolling)}
                  className={`p-1 rounded ${isReaderScrolling ? 'bg-amber-500 text-black' : 'text-zinc-400 hover:text-white'}`}
                  title={isReaderScrolling ? "Pause Scroll" : "Auto Scroll"}
                >
                  {isReaderScrolling ? <Pause className="w-3 h-3" /> : <Play className="w-3 h-3" />}
                </button>
                <div className="flex items-center space-x-2 px-2 border-l border-zinc-700">
                   <FastForward className="w-3 h-3 text-zinc-500" />
                   <input 
                    type="range" 
                    min="1" 
                    max="10" 
                    step="0.5"
                    value={readerSpeed} 
                    onChange={(e) => setReaderSpeed(parseFloat(e.target.value))}
                    className="w-16 h-1 bg-zinc-700 rounded-lg appearance-none cursor-pointer accent-amber-500"
                    title="Scroll Speed"
                   />
                </div>
             </div>
          )}

          {/* Edit Controls */}
          {onUpdate && !isEditing && !isReaderMode && (
            <button
              onClick={() => setIsEditing(true)}
              className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-zinc-800 hover:bg-zinc-700 text-xs font-medium text-zinc-300 transition-colors border border-zinc-700"
            >
              <Edit2 className="w-3 h-3" />
              <span className="hidden sm:inline">Edit</span>
            </button>
          )}

          {isEditing && (
            <div className="flex items-center space-x-2 bg-zinc-900 rounded-lg p-1 border border-zinc-700 mr-2">
              <label className="flex items-center space-x-2 px-2 py-1 cursor-pointer">
                <input 
                  type="checkbox" 
                  checked={shiftTimestamps} 
                  onChange={(e) => setShiftTimestamps(e.target.checked)}
                  className="rounded bg-zinc-700 border-zinc-600 text-red-600 focus:ring-red-500/50"
                />
                <span className="text-xs text-zinc-300 whitespace-nowrap" title="Automatically adjust subsequent timestamps when you edit a time">Shift Following</span>
              </label>
            </div>
          )}

          {isEditing && (
            <>
              <button
                onClick={saveEdits}
                className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-xs font-medium text-white transition-colors"
              >
                <Check className="w-3 h-3" />
                <span>Done</span>
              </button>
              <button
                onClick={cancelEdits}
                className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-zinc-700 hover:bg-zinc-600 text-xs font-medium text-zinc-300 transition-colors"
              >
                <X className="w-3 h-3" />
                <span>Cancel</span>
              </button>
            </>
          )}

          {/* Existing Controls - Hide some in overlay mode or edit mode to save space */}
          {!isEditing && (
            <>
              {!overlayMode && onSave && (
                <button
                  onClick={onSave}
                  className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-xs font-medium text-white transition-colors shadow-lg shadow-emerald-900/20 mr-2"
                >
                  <Save className="w-3 h-3" />
                  <span className="hidden sm:inline">Save</span>
                </button>
              )}

              {!isReaderMode && (
                <button
                  onClick={() => setAutoScroll(!autoScroll)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors border ${
                    autoScroll 
                      ? 'bg-blue-600/20 border-blue-500/50 text-blue-400 hover:bg-blue-600/30' 
                      : 'bg-zinc-800 border-zinc-700 text-zinc-400 hover:bg-zinc-700'
                  }`}
                  title="Toggle Auto-Scroll"
                >
                  {autoScroll ? 'Scroll On' : 'Scroll Off'}
                </button>
              )}

              {!overlayMode && !isReaderMode && (
                <>
                  <button onClick={() => copyToClipboard(true)} className="p-1.5 rounded-lg bg-zinc-800 text-zinc-300 hover:bg-zinc-700" title="Copy Original">
                    {copiedOriginal ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3" />}
                  </button>
                  <button onClick={() => copyToClipboard(false)} className="p-1.5 rounded-lg bg-zinc-800 text-zinc-300 hover:bg-zinc-700" title="Copy Translation">
                    {copiedTranslated ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3" />}
                  </button>
                  <button onClick={downloadSRT} className="p-1.5 rounded-lg bg-red-600 text-white hover:bg-red-500" title="Download SRT">
                    <Download className="w-3 h-3" />
                  </button>
                </>
              )}
            </>
          )}
        </div>
      </div>

      <div className={`rounded-2xl overflow-hidden flex flex-col flex-1 min-h-0 shadow-xl border
        ${overlayMode ? 'bg-black/50 border-white/10' : 'bg-zinc-900 border-zinc-800'}`}>

        {/* Table Header - Hide in Reader Mode */}
        {!isReaderMode && (
          <div className={`grid grid-cols-12 gap-4 p-4 border-b font-semibold text-zinc-500 uppercase tracking-wider sticky top-0 z-20 backdrop-blur-md
            ${overlayMode ? 'bg-black/80 border-white/10 text-[10px]' : 'bg-black/40 border-zinc-800 text-xs'}`}>
            <div className="col-span-2 text-center">Time</div>
            <div className={`${overlayMode ? 'hidden' : 'col-span-5'} pl-2`}>{data.originalLanguage || 'Original'}</div>
            <div className={`${overlayMode ? 'col-span-10 text-lg' : 'col-span-5'} pl-2 text-red-400`}>{data.translatedLanguage}</div>
          </div>
        )}

        {/* Scrollable Content */}
        <div ref={containerRef} className="overflow-y-auto custom-scrollbar flex-1 relative bg-[#0f0f0f]">
          {localSegments.length === 0 ? (
            <div className="p-12 text-center text-zinc-500 flex flex-col items-center">
              <Clock className="w-8 h-8 mb-3 opacity-50" />
              <p>No speech detected.</p>
            </div>
          ) : (
            isReaderMode ? (
              // Reader Mode View
              <div className="p-8 md:p-12 max-w-4xl mx-auto space-y-10">
                 {localSegments.map((segment, index) => {
                   const isActive = index === activeIndex;
                   return (
                     <div 
                      key={index} 
                      ref={isActive ? activeSegmentRef : null}
                      onClick={() => onSeek && onSeek(parseTimestamp(segment.startTime))}
                      className={`transition-all duration-300 cursor-pointer
                        ${isActive ? 'opacity-100' : 'opacity-60 hover:opacity-100'}
                      `}
                     >
                       <div className={`text-xs font-mono mb-3 tracking-wide flex items-center gap-2
                         ${isActive ? 'text-red-400 font-bold' : 'text-zinc-500'}`}>
                         <span>{segment.startTime}</span>
                       </div>
                       <p className="text-2xl md:text-3xl leading-[2.5] text-zinc-100 font-medium">
                         {segment.translatedText}
                       </p>
                     </div>
                   );
                 })}
                 {/* Spacer for bottom scrolling */}
                 <div className="h-[50vh]"></div>
              </div>
            ) : (
              // Standard Table View
              localSegments.map((segment, index) => {
                const isActive = index === activeIndex;
                return (
                  <div 
                    key={index}
                    ref={isActive ? activeSegmentRef : null}
                    onClick={() => !isEditing && onSeek && onSeek(parseTimestamp(segment.startTime))}
                    className={`grid grid-cols-12 gap-4 p-4 border-b transition-all duration-300 group
                      ${overlayMode ? 'border-white/5 py-3' : 'border-zinc-800/50'}
                      ${isActive 
                        ? (overlayMode ? 'bg-red-500/20 border-l-2 border-l-red-500' : 'bg-red-500/10 border-l-4 border-l-red-500') 
                        : (isEditing ? '' : 'hover:bg-zinc-800/40 cursor-pointer border-l-4 border-l-transparent')
                      }`}
                  >
                    {/* Timestamp */}
                    <div className="col-span-2 flex flex-col items-center pt-1 gap-1">
                      {isEditing ? (
                        <>
                          <input 
                            type="text"
                            className="w-full text-center bg-zinc-800/80 text-white rounded border border-zinc-700 focus:border-red-500 outline-none text-[10px] md:text-xs py-1"
                            value={segment.startTime}
                            onFocus={() => handleTimestampFocus(segment.startTime)}
                            onBlur={(e) => handleTimestampBlur(index, 'startTime', e.target.value)}
                            onChange={(e) => handleSegmentChange(index, 'startTime', e.target.value)}
                          />
                          <div className="text-[9px] text-zinc-600">to</div>
                          <input 
                            type="text"
                            className="w-full text-center bg-zinc-800/80 text-zinc-400 rounded border border-zinc-700 focus:border-red-500 outline-none text-[10px] md:text-xs py-1"
                            value={segment.endTime}
                            onFocus={() => handleTimestampFocus(segment.endTime)}
                            onBlur={(e) => handleTimestampBlur(index, 'endTime', e.target.value)}
                            onChange={(e) => handleSegmentChange(index, 'endTime', e.target.value)}
                          />
                        </>
                      ) : (
                        <div className={`flex items-center space-x-1 font-mono rounded transition-colors
                          ${overlayMode ? 'text-[10px] px-1' : 'text-xs px-2 py-1'}
                          ${isActive ? 'text-red-300 bg-red-500/20' : 'text-zinc-500 bg-zinc-800/50'}`}>
                          {!overlayMode && <Play className={`w-2 h-2 ${isActive ? 'fill-current' : 'hidden group-hover:block'}`} />}
                          <span>{segment.startTime}</span>
                        </div>
                      )}
                    </div>

                    {/* Original Text */}
                    <div className={`${overlayMode ? 'hidden' : 'col-span-5'} pl-2 leading-relaxed transition-colors
                      ${overlayMode ? 'text-xs' : 'text-sm md:text-base'}
                      ${isActive ? 'text-white' : 'text-zinc-400 group-hover:text-zinc-300'}`}>
                      {isEditing ? (
                        <textarea 
                          id={`original-text-${index}`}
                          className="w-full bg-zinc-800/50 text-white p-2 rounded border border-zinc-700 focus:border-red-500 outline-none resize-none text-xs"
                          rows={6}
                          value={segment.originalText}
                          onChange={(e) => handleSegmentChange(index, 'originalText', e.target.value)}
                        />
                      ) : (
                        segment.originalText
                      )}
                    </div>

                    {/* Translated Text */}
                    <div className={`${overlayMode ? 'col-span-10 text-xl md:text-2xl' : 'col-span-5 text-sm md:text-base'} pl-2 leading-relaxed font-medium transition-colors
                      ${isActive ? 'text-red-100' : 'text-zinc-200 group-hover:text-white'}`}>
                      {isEditing ? (
                        <textarea 
                          className="w-full bg-zinc-800/50 text-white p-2 rounded border border-zinc-700 focus:border-red-500 outline-none resize-none text-xs"
                          rows={6}
                          value={segment.translatedText}
                          onChange={(e) => handleSegmentChange(index, 'translatedText', e.target.value)}
                        />
                      ) : (
                        segment.translatedText
                      )}
                    </div>
                  </div>
                );
              })
            )
          )}
        </div>
      </div>
    </div>
  );
};

export default TranscriptDisplay;

import React, { useState, useEffect, useRef } from 'react';
import { TranscriptResult, TranscriptSegment } from '../types';
import { Copy, Check, Download, Clock, Play, Save, Edit2, X, BookOpen, Pause, FastForward } from 'lucide-react';

interface TranscriptDisplayProps {
  data: TranscriptResult;
  currentTime?: number;
  onSeek?: (time: number) => void;
  onSave?: () => void;
  onUpdate?: (updatedData: TranscriptResult) => void;
  overlayMode?: boolean;
}

const parseTimestamp = (timeStr: string): number => {
  if (!timeStr) return 0;
  const parts = timeStr.split(':').map(Number);
  if (parts.some(isNaN)) return NaN;
  if (parts.length === 2) return parts[0] * 60 + parts[1];
  if (parts.length === 3) return parts[0] * 3600 + parts[1] * 60 + parts[2];
  return 0;
};

const formatTimestamp = (totalSeconds: number): string => {
  if (isNaN(totalSeconds) || totalSeconds < 0) return "00:00";
  const h = Math.floor(totalSeconds / 3600);
  const m = Math.floor((totalSeconds % 3600) / 60);
  const s = Math.floor(totalSeconds % 60);
  if (h > 0) {
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  }
  return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
};

const TranscriptDisplay: React.FC<TranscriptDisplayProps> = ({ 
  data, 
  currentTime = 0, 
  onSeek,
  onSave,
  onUpdate,
  overlayMode = false
}) => {
  const [copiedOriginal, setCopiedOriginal] = useState(false);
  const [copiedTranslated, setCopiedTranslated] = useState(false);
  const [autoScroll, setAutoScroll] = useState(true);
  const [isEditing, setIsEditing] = useState(false);
  const [localSegments, setLocalSegments] = useState<TranscriptSegment[]>(data.segments);
  const [shiftTimestamps, setShiftTimestamps] = useState(true);
  const [focusTime, setFocusTime] = useState<number | null>(null);

  // Reader Mode State
  const [isReaderMode, setIsReaderMode] = useState(false);
  const [isReaderScrolling, setIsReaderScrolling] = useState(false);
  const [readerSpeed, setReaderSpeed] = useState(1); // 1 = slow, 5 = fast

  const activeSegmentRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Sync local state when data changes externally (unless we are in the middle of editing)
  useEffect(() => {
    if (!isEditing) {
      setLocalSegments(data.segments);
    }
  }, [data, isEditing]);

  // Find active segment
  const activeIndex = localSegments.findIndex((seg, index) => {
    const start = parseTimestamp(seg.startTime);
    const nextSeg = localSegments[index + 1];
    const end = nextSeg ? parseTimestamp(nextSeg.startTime) : parseTimestamp(seg.endTime);
    return currentTime >= start && currentTime < end;
  });

  // Auto-focus on Edit Mode
  useEffect(() => {
    if (isEditing && activeIndex !== -1) {
      setTimeout(() => {
        const el = document.getElementById(`original-text-${activeIndex}`);
        if (el) {
          el.focus();
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 100);
    }
  }, [isEditing]); // Only run when entering edit mode

  // Standard Auto-scroll effect (Sync with video)
  useEffect(() => {
    if (autoScroll && !isReaderMode && activeIndex !== -1 && activeSegmentRef.current && !isEditing) {
      activeSegmentRef.current.scrollIntoView({ 
        behavior: 'smooth', 
        block: 'center' 
      });
    }
  }, [activeIndex, autoScroll, isEditing, isReaderMode]);

  // Reader Mode Teleprompter Scroll
  useEffect(() => {
    let animationFrameId: number;
    let lastTime: number = 0;

    const animateScroll = (timestamp: number) => {
      if (!lastTime) lastTime = timestamp;
      const deltaTime = timestamp - lastTime;

      if (isReaderScrolling && containerRef.current && deltaTime >= 16) { // ~60fps
         // Speed factor: 1 = 0.5px/frame, 10 = 5px/frame
         // Reduced to ~70% of previous 0.3 value (0.21)
         const pxPerFrame = readerSpeed * 0.21;
         containerRef.current.scrollTop += pxPerFrame;
         lastTime = timestamp;
      }

      if (isReaderScrolling) {
        animationFrameId = requestAnimationFrame(animateScroll);
      }
    };

    if (isReaderScrolling) {
      animationFrameId = requestAnimationFrame(animateScroll);
    }

    return () => cancelAnimationFrame(animationFrameId);
  }, [isReaderScrolling, readerSpeed]);

  const handleSegmentChange = (index: number, field: keyof TranscriptSegment, value: string) => {
    const newSegments = [...localSegments];
    newSegments[index] = { ...newSegments[index], [field]: value };
    setLocalSegments(newSegments);
  };

  const handleTimestampFocus = (timeStr: string) => {
    const time = parseTimestamp(timeStr);
    if (!isNaN(time)) {
      setFocusTime(time);
    }
  };

  const handleTimestampBlur = (index: number, field: 'startTime' | 'endTime', value: string) => {
    if (focusTime === null) return;

    const newTime = parseTimestamp(value);

    // If invalid format, revert to original focus time
    if (isNaN(newTime)) {
      const newSegments = [...localSegments];
      newSegments[index] = { ...newSegments[index], [field]: formatTimestamp(focusTime) };
      setLocalSegments(newSegments);
      setFocusTime(null);
      return;
    }

    const delta = newTime - focusTime;

    // If no change, do nothing
    if (delta === 0) {
      setFocusTime(null);
      return;
    }

    // Apply updates
    const newSegments = [...localSegments];

    // Format the current field correctly
    newSegments[index] = { ...newSegments[index], [field]: formatTimestamp(newTime) };

    if (shiftTimestamps) {
      // If editing StartTime: Shift EndTime of current + Start/End of all subsequent
      if (field === 'startTime') {
        const currentEnd = parseTimestamp(newSegments[index].endTime);
        if (!isNaN(currentEnd)) {
           newSegments[index].endTime = formatTimestamp(currentEnd + delta);
        }
      }

      // Shift all subsequent segments
      for (let i = index + 1; i < newSegments.length; i++) {
        const sStart = parseTimestamp(newSegments[i].startTime);
        const sEnd = parseTimestamp(newSegments[i].endTime);

        if (!isNaN(sStart)) newSegments[i].startTime = formatTimestamp(sStart + delta);
        if (!isNaN(sEnd)) newSegments[i].endTime = formatTimestamp(sEnd + delta);
      }
    }

    setLocalSegments(newSegments);
    setFocusTime(null);
  };

  const saveEdits = () => {
    // Filter out segments where both text fields are empty
    const validSegments = localSegments.filter(seg => 
      seg.originalText.trim().length > 0 || seg.translatedText.trim().length > 0
    );

    if (onUpdate) {
      onUpdate({ ...data, segments: validSegments });
    }

    setLocalSegments(validSegments);
    setIsEditing(false);
  };

  const cancelEdits = () => {
    setLocalSegments(data.segments);
    setIsEditing(false);
  };

  const getFullText = (isOriginal: boolean) => {
    return localSegments
      .map(s => isOriginal ? s.originalText : s.translatedText)
      .join('\n');
  };

  const copyToClipboard = async (isOriginal: boolean) => {
    try {
      const text = getFullText(isOriginal);
      await navigator.clipboard.writeText(text);
      if (isOriginal) {
        setCopiedOriginal(true);
        setTimeout(() => setCopiedOriginal(false), 2000);
      } else {
        setCopiedTranslated(true);
        setTimeout(() => setCopiedTranslated(false), 2000);
      }
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  const downloadSRT = () => {
    let srtContent = '';
    localSegments.forEach((segment, index) => {
      const formatTime = (time: string) => {
        const parts = time.split(':');
        if (parts.length === 2) return `00:${time},000`;
        return `${time},000`;
      };
      srtContent += `${index + 1}\n`;
      srtContent += `${formatTime(segment.startTime)} --> ${formatTime(segment.endTime)}\n`;
      srtContent += `${segment.originalText}\n`;
      srtContent += `${segment.translatedText}\n\n`;
    });

    const blob = new Blob([srtContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `transcript_${data.originalLanguage}_to_${data.translatedLanguage}.srt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className={`w-full flex flex-col h-full bg-[#0f0f0f] ${overlayMode ? 'text-sm' : ''}`}>
      {/* Header Toolbar - Fixed Top */}
      <div className={`flex flex-wrap justify-between items-center gap-4 flex-shrink-0 mb-4 bg-[#0f0f0f] z-30 py-2 ${overlayMode ? 'sticky top-0 px-2' : 'sticky top-16'}`}>
        {!overlayMode && <h2 className="text-xl font-bold text-white">Transcript</h2>}

        <div className="flex flex-wrap gap-2 ml-auto items-center">

          {/* Reader Mode Toggle */}
          {!isEditing && (
            <button
              onClick={() => {
                setIsReaderMode(!isReaderMode);
                setIsReaderScrolling(false); // Stop auto scroll when switching modes
              }}
              className={`flex items-center space-x-2 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors border
                ${isReaderMode 
                  ? 'bg-amber-600/20 border-amber-500/50 text-amber-400 hover:bg-amber-600/30' 
                  : 'bg-zinc-800 border-zinc-700 text-zinc-400 hover:bg-zinc-700'
                }`}
            >
              <BookOpen className="w-3 h-3" />
              <span className="hidden sm:inline">Reader Mode</span>
            </button>
          )}

          {/* Reader Mode Controls */}
          {isReaderMode && (
             <div className="flex items-center space-x-2 bg-zinc-900 rounded-lg p-1 border border-zinc-700 mr-2">
                <button
                  onClick={() => setIsReaderScrolling(!isReaderScrolling)}
                  className={`p-1 rounded ${isReaderScrolling ? 'bg-amber-500 text-black' : 'text-zinc-400 hover:text-white'}`}
                  title={isReaderScrolling ? "Pause Scroll" : "Auto Scroll"}
                >
                  {isReaderScrolling ? <Pause className="w-3 h-3" /> : <Play className="w-3 h-3" />}
                </button>
                <div className="flex items-center space-x-2 px-2 border-l border-zinc-700">
                   <FastForward className="w-3 h-3 text-zinc-500" />
                   <input 
                    type="range" 
                    min="1" 
                    max="10" 
                    step="0.5"
                    value={readerSpeed} 
                    onChange={(e) => setReaderSpeed(parseFloat(e.target.value))}
                    className="w-16 h-1 bg-zinc-700 rounded-lg appearance-none cursor-pointer accent-amber-500"
                    title="Scroll Speed"
                   />
                </div>
             </div>
          )}

          {/* Edit Controls */}
          {onUpdate && !isEditing && !isReaderMode && (
            <button
              onClick={() => setIsEditing(true)}
              className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-zinc-800 hover:bg-zinc-700 text-xs font-medium text-zinc-300 transition-colors border border-zinc-700"
            >
              <Edit2 className="w-3 h-3" />
              <span className="hidden sm:inline">Edit</span>
            </button>
          )}

          {isEditing && (
            <div className="flex items-center space-x-2 bg-zinc-900 rounded-lg p-1 border border-zinc-700 mr-2">
              <label className="flex items-center space-x-2 px-2 py-1 cursor-pointer">
                <input 
                  type="checkbox" 
                  checked={shiftTimestamps} 
                  onChange={(e) => setShiftTimestamps(e.target.checked)}
                  className="rounded bg-zinc-700 border-zinc-600 text-red-600 focus:ring-red-500/50"
                />
                <span className="text-xs text-zinc-300 whitespace-nowrap" title="Automatically adjust subsequent timestamps when you edit a time">Shift Following</span>
              </label>
            </div>
          )}

          {isEditing && (
            <>
              <button
                onClick={saveEdits}
                className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-xs font-medium text-white transition-colors"
              >
                <Check className="w-3 h-3" />
                <span>Done</span>
              </button>
              <button
                onClick={cancelEdits}
                className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-zinc-700 hover:bg-zinc-600 text-xs font-medium text-zinc-300 transition-colors"
              >
                <X className="w-3 h-3" />
                <span>Cancel</span>
              </button>
            </>
          )}

          {/* Existing Controls - Hide some in overlay mode or edit mode to save space */}
          {!isEditing && (
            <>
              {!overlayMode && onSave && (
                <button
                  onClick={onSave}
                  className="flex items-center space-x-2 px-3 py-1.5 rounded-lg bg-emerald-600 hover:bg-emerald-500 text-xs font-medium text-white transition-colors shadow-lg shadow-emerald-900/20 mr-2"
                >
                  <Save className="w-3 h-3" />
                  <span className="hidden sm:inline">Save</span>
                </button>
              )}

              {!isReaderMode && (
                <button
                  onClick={() => setAutoScroll(!autoScroll)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors border ${
                    autoScroll 
                      ? 'bg-blue-600/20 border-blue-500/50 text-blue-400 hover:bg-blue-600/30' 
                      : 'bg-zinc-800 border-zinc-700 text-zinc-400 hover:bg-zinc-700'
                  }`}
                  title="Toggle Auto-Scroll"
                >
                  {autoScroll ? 'Scroll On' : 'Scroll Off'}
                </button>
              )}

              {!overlayMode && !isReaderMode && (
                <>
                  <button onClick={() => copyToClipboard(true)} className="p-1.5 rounded-lg bg-zinc-800 text-zinc-300 hover:bg-zinc-700" title="Copy Original">
                    {copiedOriginal ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3" />}
                  </button>
                  <button onClick={() => copyToClipboard(false)} className="p-1.5 rounded-lg bg-zinc-800 text-zinc-300 hover:bg-zinc-700" title="Copy Translation">
                    {copiedTranslated ? <Check className="w-3 h-3 text-green-500" /> : <Copy className="w-3 h-3" />}
                  </button>
                  <button onClick={downloadSRT} className="p-1.5 rounded-lg bg-red-600 text-white hover:bg-red-500" title="Download SRT">
                    <Download className="w-3 h-3" />
                  </button>
                </>
              )}
            </>
          )}
        </div>
      </div>

      <div className={`rounded-2xl overflow-hidden flex flex-col flex-1 min-h-0 shadow-xl border
        ${overlayMode ? 'bg-black/50 border-white/10' : 'bg-zinc-900 border-zinc-800'}`}>

        {/* Table Header - Hide in Reader Mode */}
        {!isReaderMode && (
          <div className={`grid grid-cols-12 gap-4 p-4 border-b font-semibold text-zinc-500 uppercase tracking-wider sticky top-0 z-20 backdrop-blur-md
            ${overlayMode ? 'bg-black/80 border-white/10 text-[10px]' : 'bg-black/40 border-zinc-800 text-xs'}`}>
            <div className="col-span-2 text-center">Time</div>
            <div className={`${overlayMode ? 'hidden' : 'col-span-5'} pl-2`}>{data.originalLanguage || 'Original'}</div>
            <div className={`${overlayMode ? 'col-span-10 text-lg' : 'col-span-5'} pl-2 text-red-400`}>{data.translatedLanguage}</div>
          </div>
        )}

        {/* Scrollable Content */}
        <div ref={containerRef} className="overflow-y-auto custom-scrollbar flex-1 relative bg-[#0f0f0f]">
          {localSegments.length === 0 ? (
            <div className="p-12 text-center text-zinc-500 flex flex-col items-center">
              <Clock className="w-8 h-8 mb-3 opacity-50" />
              <p>No speech detected.</p>
            </div>
          ) : (
            isReaderMode ? (
              // Reader Mode View
              <div className="p-8 md:p-12 max-w-4xl mx-auto space-y-10">
                 {localSegments.map((segment, index) => {
                   const isActive = index === activeIndex;
                   return (
                     <div 
                      key={index} 
                      ref={isActive ? activeSegmentRef : null}
                      onClick={() => onSeek && onSeek(parseTimestamp(segment.startTime))}
                      className={`transition-all duration-300 cursor-pointer
                        ${isActive ? 'opacity-100' : 'opacity-60 hover:opacity-100'}
                      `}
                     >
                       <div className={`text-xs font-mono mb-3 tracking-wide flex items-center gap-2
                         ${isActive ? 'text-red-400 font-bold' : 'text-zinc-500'}`}>
                         <span>{segment.startTime}</span>
                       </div>
                       <p className="text-2xl md:text-3xl leading-[2.5] text-zinc-100 font-medium">
                         {segment.translatedText}
                       </p>
                     </div>
                   );
                 })}
                 {/* Spacer for bottom scrolling */}
                 <div className="h-[50vh]"></div>
              </div>
            ) : (
              // Standard Table View
              localSegments.map((segment, index) => {
                const isActive = index === activeIndex;
                return (
                  <div 
                    key={index}
                    ref={isActive ? activeSegmentRef : null}
                    onClick={() => !isEditing && onSeek && onSeek(parseTimestamp(segment.startTime))}
                    className={`grid grid-cols-12 gap-4 p-4 border-b transition-all duration-300 group
                      ${overlayMode ? 'border-white/5 py-3' : 'border-zinc-800/50'}
                      ${isActive 
                        ? (overlayMode ? 'bg-red-500/20 border-l-2 border-l-red-500' : 'bg-red-500/10 border-l-4 border-l-red-500') 
                        : (isEditing ? '' : 'hover:bg-zinc-800/40 cursor-pointer border-l-4 border-l-transparent')
                      }`}
                  >
                    {/* Timestamp */}
                    <div className="col-span-2 flex flex-col items-center pt-1 gap-1">
                      {isEditing ? (
                        <>
                          <input 
                            type="text"
                            className="w-full text-center bg-zinc-800/80 text-white rounded border border-zinc-700 focus:border-red-500 outline-none text-[10px] md:text-xs py-1"
                            value={segment.startTime}
                            onFocus={() => handleTimestampFocus(segment.startTime)}
                            onBlur={(e) => handleTimestampBlur(index, 'startTime', e.target.value)}
                            onChange={(e) => handleSegmentChange(index, 'startTime', e.target.value)}
                          />
                          <div className="text-[9px] text-zinc-600">to</div>
                          <input 
                            type="text"
                            className="w-full text-center bg-zinc-800/80 text-zinc-400 rounded border border-zinc-700 focus:border-red-500 outline-none text-[10px] md:text-xs py-1"
                            value={segment.endTime}
                            onFocus={() => handleTimestampFocus(segment.endTime)}
                            onBlur={(e) => handleTimestampBlur(index, 'endTime', e.target.value)}
                            onChange={(e) => handleSegmentChange(index, 'endTime', e.target.value)}
                          />
                        </>
                      ) : (
                        <div className={`flex items-center space-x-1 font-mono rounded transition-colors
                          ${overlayMode ? 'text-[10px] px-1' : 'text-xs px-2 py-1'}
                          ${isActive ? 'text-red-300 bg-red-500/20' : 'text-zinc-500 bg-zinc-800/50'}`}>
                          {!overlayMode && <Play className={`w-2 h-2 ${isActive ? 'fill-current' : 'hidden group-hover:block'}`} />}
                          <span>{segment.startTime}</span>
                        </div>
                      )}
                    </div>

                    {/* Original Text */}
                    <div className={`${overlayMode ? 'hidden' : 'col-span-5'} pl-2 leading-relaxed transition-colors
                      ${overlayMode ? 'text-xs' : 'text-sm md:text-base'}
                      ${isActive ? 'text-white' : 'text-zinc-400 group-hover:text-zinc-300'}`}>
                      {isEditing ? (
                        <textarea 
                          id={`original-text-${index}`}
                          className="w-full bg-zinc-800/50 text-white p-3 rounded-xl border border-zinc-700 focus:border-red-500 outline-none resize-y text-base leading-relaxed"
                          rows={10}
                          value={segment.originalText}
                          onChange={(e) => handleSegmentChange(index, 'originalText', e.target.value)}
                        />
                      ) : (
                        segment.originalText
                      )}
                    </div>

                    {/* Translated Text */}
                    <div className={`${overlayMode ? 'col-span-10 text-xl md:text-2xl' : 'col-span-5 text-sm md:text-base'} pl-2 leading-relaxed font-medium transition-colors
                      ${isActive ? 'text-red-100' : 'text-zinc-200 group-hover:text-white'}`}>
                      {isEditing ? (
                        <textarea 
                          className="w-full bg-zinc-800/50 text-white p-3 rounded-xl border border-zinc-700 focus:border-red-500 outline-none resize-y text-xl leading-relaxed"
                          rows={10}
                          value={segment.translatedText}
                          onChange={(e) => handleSegmentChange(index, 'translatedText', e.target.value)}
                        />
                      ) : (
                        segment.translatedText
                      )}
                    </div>
                  </div>
                );
              })
            )
          )}
        </div>
      </div>
    </div>
  );
};

export default TranscriptDisplay;
